    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What are the five components of the APGAR score?', '["Appearance, Pulse, Grimace, Activity, Respiration", "Airway, Pulse, Growth, Activity, Reflexes", "Appearance, Pressure, Grimace, Airway, Respiration", "Activity, Pulse, Girth, Appearance, Respiration"]', 0, 'APGAR stands for Appearance (color), Pulse (heart rate), Grimace (reflex irritability), Activity (muscle tone), and Respiration. (Nelson)'),
    (v_topic_id, '2: A newborn at 1 minute of life has a heart rate of 90 bpm, slow/irregular respirations, some flexion of extremities, grimaces to stimulation, and has a pink body with blue extremities (acrocyanosis). What is the APGAR score?', '["4", "5", "6", "7"]', 1, 'Pulse < 100 (1), Resp slow (1), Tone some flexion (1), Grimace (1), Color acrocyanosis (1). Total = 5. (UWorld)'),
    (v_topic_id, '3: At what times are APGAR scores routinely assigned after birth?', '["1 and 5 minutes", "1, 5, and 10 minutes", "1 and 3 minutes", "5 and 10 minutes"]', 0, 'Routinely at 1 and 5 minutes. If the 5-minute score is < 7, it is repeated every 5 minutes until 20 minutes of life. (NRP Guidelines)'),
    (v_topic_id, '4: During neonatal resuscitation, what is the single most important and effective action?', '["Chest compressions", "Epinephrine administration", "Ventilation of the lungs", "Fluid bolus"]', 2, 'Establishing effective ventilation is the most critical step in neonatal resuscitation, as almost all neonatal arrests are respiratory in origin. (NRP Guidelines)'),
    (v_topic_id, '5: An infant is born apneic and limp. After warming, drying, and stimulating, the infant remains apneic and the heart rate is 80 bpm. What is the immediate next step?', '["Provide Positive Pressure Ventilation (PPV)", "Start chest compressions", "Administer intravenous epinephrine", "Provide continuous positive airway pressure (CPAP)"]', 0, 'If HR < 100 or the infant is apneic/gasping after initial steps, begin PPV immediately. (NRP Guidelines)'),
    (v_topic_id, '6: After 30 seconds of effective Positive Pressure Ventilation (PPV) that moves the chest, a neonate''s heart rate drops to 50 bpm. What is the next step?",', '["Continue PPV for another 30 seconds", "Administer IV epinephrine", "Begin chest compressions and continue PPV", "Administer normal saline bolus"]', 2, 'Chest compressions are indicated if the HR remains < 60 bpm despite at least 30 seconds of adequate PPV. (NRP Guidelines)'),
    (v_topic_id, '7: What is the recommended compression-to-ventilation ratio for a neonate requiring chest compressions during resuscitation?",', '["15:2", "30:2", "3:1", "1:1"]', 2, 'The neonatal ratio is 3 compressions to 1 ventilation, achieving 90 compressions and 30 breaths per minute. (NRP Guidelines)'),
    (v_topic_id, '8: A premature infant (28 weeks gestation) develops grunting, flaring, and retractions shortly after birth. Chest X-ray shows a diffuse reticulogranular ground-glass appearance with air bronchograms. Diagnosis?",', '["Transient Tachypnea of the Newborn (TTN)", "Meconium Aspiration Syndrome (MAS)", "Respiratory Distress Syndrome (RDS)", "Neonatal Pneumonia"]', 2, 'Classic presentation of RDS (Hyaline Membrane Disease) due to surfactant deficiency in prematurity. (First Aid)'),
    (v_topic_id, '9: What is the primary pathophysiology behind Respiratory Distress Syndrome (RDS) in premature infants?",', '["Retained fetal lung fluid", "Deficiency of pulmonary surfactant", "Aspiration of meconium", "Bacterial infection of the lung parenchyma"]', 1, 'Lack of surfactant leads to high surface tension, alveolar collapse (atelectasis), and decreased lung compliance. (Nelson)'),
    (v_topic_id, '10: A pregnant woman at 30 weeks gestation presents in preterm labor. What medication should be administered to accelerate fetal lung maturity and prevent RDS?",', '["Intravenous magnesium sulfate", "Intramuscular betamethasone or dexamethasone", "Intravenous antibiotics", "Oral terbutaline"]', 1, 'Antenatal corticosteroids are the standard of care for women at risk of preterm delivery < 34 weeks. (ACOG/UWorld)'),
    (v_topic_id, '11: A term infant delivered via elective Cesarean section (without labor) develops tachypnea and mild retractions at 2 hours of life. Chest X-ray reveals prominent perihilar streaking and fluid in the interlobar fissures. Diagnosis?",', '["Respiratory Distress Syndrome (RDS)", "Transient Tachypnea of the Newborn (TTN)", "Neonatal sepsis", "Congenital diaphragmatic hernia"]', 1, 'TTN is caused by delayed clearance of fetal lung fluid. It is common after C-sections because the mechanical squeeze of labor is absent. (Case Files)'),
    (v_topic_id, '12: What is the typical clinical course and management of Transient Tachypnea of the Newborn (TTN)?",', '["Requires intubation and surfactant administration; resolves in 1 week", "Self-limiting condition resolving in 24-48 hours; managed with supportive care (e.g., supplemental oxygen, CPAP)", "High mortality rate without ECMO", "Requires immediate antibiotics for 14 days"]', 1, 'TTN is benign and self-limiting as the lymphatic system slowly absorbs the remaining lung fluid. (Amboss)'),
    (v_topic_id, '13: A post-term infant (42 weeks gestation) is born through thick, pea-soup amniotic fluid. The infant is depressed at birth and develops severe respiratory distress. Chest X-ray shows patchy infiltrates, hyperinflation, and a flattened diaphragm. Diagnosis?",', '["Transient Tachypnea of the Newborn", "Respiratory Distress Syndrome", "Meconium Aspiration Syndrome (MAS)", "Neonatal Pneumonia"]', 2, 'MAS typically occurs in term or post-term infants. Meconium causes airway obstruction (ball-valve effect leading to hyperinflation) and chemical pneumonitis. (Nelson)'),
    (v_topic_id, '14: An infant with Meconium Aspiration Syndrome develops severe hypoxemia out of proportion to the parenchymal lung disease, with a pre-ductal to post-ductal SpO2 gradient of 15%. What major complication has occurred?",', '["Pneumothorax", "Persistent Pulmonary Hypertension of the Newborn (PPHN)", "Sepsis", "Heart failure"]', 1, 'PPHN involves high pulmonary vascular resistance, causing right-to-left shunting across the PDA and foramen ovale, leading to profound hypoxemia. (First Aid)'),
    (v_topic_id, '15: What is a cornerstone medical therapy for severe Persistent Pulmonary Hypertension of the Newborn (PPHN)?",', '["Inhaled nitric oxide (iNO)", "Intravenous indomethacin", "Oral propranolol", "Inhaled albuterol"]', 0, 'Inhaled nitric oxide is a selective pulmonary vasodilator that rapidly decreases pulmonary vascular resistance and improves oxygenation. (UWorld)'),
    (v_topic_id, '16: Which of the following is an expected physiologic change in the neonatal cardiovascular system immediately after birth?",', '["Increase in pulmonary vascular resistance", "Closure of the ductus venosus, followed by closure of the ductus arteriosus and foramen ovale", "Decrease in systemic vascular resistance", "Right-to-left shunting across the ductus arteriosus"]', 1, 'Clamping the cord increases systemic vascular resistance; breathing oxygen decreases pulmonary vascular resistance, reversing pressures and closing the shunts. (Nelson)'),
    (v_topic_id, '17: A newborn is noted to have a scaphoid abdomen, severe respiratory distress, and absent breath sounds on the left side. Heart sounds are displaced to the right. Diagnosis?",', '["Congenital Diaphragmatic Hernia (CDH)", "Pneumothorax", "Tracheoesophageal fistula", "Cystic adenomatoid malformation"]', 0, 'CDH allows abdominal organs to herniate into the chest, compressing the developing lung (pulmonary hypoplasia) and shifting the mediastinum. (Amboss)'),
    (v_topic_id, '18: What is the most appropriate immediate intervention for a neonate suspected of having a Congenital Diaphragmatic Hernia?",', '["Bag-mask ventilation", "Endotracheal intubation and placement of a gastric tube (Replogle)", "Needle thoracostomy", "Administration of surfactant"]', 1, 'Bag-mask ventilation is CONTRAINDICATED as it inflates the stomach/intestines in the chest, worsening lung compression. Immediate intubation and gastric decompression are required. (UWorld)'),
    (v_topic_id, '19: A newborn presents with excessive salivation, choking, and cyanosis upon the first feeding. An attempt to pass an orogastric tube meets resistance and coils in the upper esophagus. Diagnosis?",', '["Pyloric stenosis", "Esophageal Atresia (EA) with Tracheoesophageal Fistula (TEF)", "Duodenal atresia", "Choanal atresia"]', 1, 'EA/TEF prevents swallowing and leads to aspiration. The most common type is proximal esophageal atresia with a distal TEF. (Case Files)'),
    (v_topic_id, '20: What classic finding on prenatal ultrasound suggests Esophageal Atresia or Duodenal Atresia?",', '["Oligohydramnios", "Polyhydramnios", "Echogenic bowel", "Fetal hydrops"]', 1, 'Polyhydramnios occurs because the fetus cannot swallow and absorb amniotic fluid in the gastrointestinal tract. (First Aid)'),
    (v_topic_id, '21: A term infant presents with cyanosis that worsens with feeding and crying but improves when the infant is crying with their mouth open. What is the most likely diagnosis?",', '["Tetralogy of Fallot", "Bilateral Choanal Atresia", "Transposition of the Great Arteries", "Tracheomalacia"]', 1, 'Neonates are obligate nasal breathers. Bilateral choanal atresia causes cyanosis at rest/feeding that improves when crying opens the oral airway. (Nelson)'),
    (v_topic_id, '22: Jaundice appearing within the first 24 hours of life is considered:",', '["Physiologic", "Always pathologic and requires immediate investigation", "Breast milk jaundice", "Normal variant"]', 1, 'Visible jaundice in the first 24 hours is pathologic (e.g., hemolysis from ABO/Rh incompatibility, sepsis, TORCH) and must be evaluated. (Case Files)'),
    (v_topic_id, '23: Which of the following best describes physiologic jaundice in a full-term neonate?",', '["Direct (conjugated) hyperbilirubinemia peaking at day 14", "Indirect (unconjugated) hyperbilirubinemia peaking around day 3-5 of life and resolving by 1-2 weeks", "Jaundice that persists beyond 3 weeks", "Jaundice associated with pale stools and dark urine"]', 1, 'Physiologic jaundice results from high RBC turnover and immature hepatic UDP-glucuronosyltransferase activity. (Amboss)'),
    (v_topic_id, '24: A 4-day-old exclusively breastfed infant presents with jaundice. The infant has lost 12% of their birth weight, has decreased urine output, and feeds only 4 times a day. What is the most likely diagnosis?",', '["Breast milk jaundice", "Breastfeeding failure jaundice (lactation failure jaundice)", "Biliary atresia", "ABO incompatibility"]', 1, 'Caused by inadequate intake, leading to dehydration and decreased bowel movements, which increases enterohepatic circulation of bilirubin. Occurs in the first week. (UWorld)'),
    (v_topic_id, '25: What is the most appropriate management for breastfeeding failure jaundice?",', '["Stop breastfeeding entirely and switch to formula", "Increase breastfeeding frequency (e.g., every 2-3 hours) and duration; consider formula supplementation if severe", "Administer IV immunoglobulin (IVIG)", "Order an urgent Kasai portoenterostomy"]', 1, 'The goal is to increase enteral intake to promote bowel movements and bilirubin excretion. (Nelson)'),
    (v_topic_id, '26: A 2-week-old thriving, exclusively breastfed infant has mild, persistent jaundice. Weight gain is excellent. Total bilirubin is 12 mg/dL (mostly indirect). What is the most likely diagnosis?",', '["Breast milk jaundice", "Breastfeeding failure jaundice", "Biliary atresia", "G6PD deficiency"]', 0, 'Occurs after the first week and peaks at 2-3 weeks. Thought to be due to factors in breast milk (e.g., beta-glucuronidase) that increase enterohepatic circulation. Benign. (First Aid)'),
    (v_topic_id, '27: A 1-day-old infant develops rapidly worsening jaundice. Blood type of the mother is O positive; the infant is A positive. Direct antiglobulin test (DAT/Coombs) is positive. What is the mechanism of hyperbilirubinemia?",', '["Decreased bilirubin conjugation", "Alloimmune hemolytic disease of the newborn (ABO incompatibility)", "Red blood cell enzyme defect", "Biliary obstruction"]', 1, 'Maternal anti-A IgG antibodies cross the placenta and destroy fetal A-positive RBCs, leading to unconjugated hyperbilirubinemia within 24 hours. (Case Files)'),
    (v_topic_id, '28: What is the primary toxicity associated with severe, untreated indirect (unconjugated) hyperbilirubinemia in a neonate?",', '["Hepatic cirrhosis", "Kernicterus (Bilirubin-induced neurologic dysfunction)", "Renal failure", "Pulmonary fibrosis"]', 1, 'Unconjugated bilirubin is lipid-soluble and crosses the blood-brain barrier, depositing in the basal ganglia and brainstem, causing irreversible brain damage. (Nelson)'),
    (v_topic_id, '29: What are the classic late clinical signs of kernicterus?",', '["Choreothetoid cerebral palsy, sensorineural hearing loss, and upward gaze palsy", "Spastic diplegia, blindness, and macrocephaly", "Intractable seizures, hepatomegaly, and ascites", "Microcephaly, cataracts, and patent ductus arteriosus"]', 0, 'The classic triad of kernicterus. (First Aid)'),
    (v_topic_id, '30: What is the mechanism of action of phototherapy in the treatment of neonatal hyperbilirubinemia?",', '["It increases the production of UDP-glucuronosyltransferase in the liver", "It converts unconjugated bilirubin into water-soluble isomers (lumirubin) that can be excreted in urine and bile without conjugation", "It binds bilirubin in the gut to prevent enterohepatic circulation", "It induces hemolysis of antibody-coated RBCs"]', 1, 'Photoisomerization is the key mechanism, allowing bypass of the immature liver enzymes. (UWorld)'),
    (v_topic_id, '31: If an infant''s total bilirubin rapidly approaches the exchange transfusion threshold despite intensive phototherapy, what medication can be given, particularly in cases of isoimmune hemolysis?",', '["Phenobarbital", "Intravenous Immunoglobulin (IVIG)", "Ursodeoxycholic acid", "Corticosteroids"]', 1, 'IVIG blocks Fc receptors on macrophages in the reticuloendothelial system, halting the destruction of antibody-coated RBCs. (Amboss)'),
    (v_topic_id, '32: A 4-week-old infant presents with persistent jaundice, acholic (pale) stools, and dark urine. Labs show a total bilirubin of 8 mg/dL with a direct (conjugated) fraction of 5 mg/dL. What is the most urgent diagnosis to rule out?",', '["Physiologic jaundice", "Breast milk jaundice", "Biliary atresia", "Gilbert syndrome"]', 2, 'Conjugated (direct) hyperbilirubinemia is NEVER physiologic. Acholic stools and dark urine suggest obstructive jaundice. Biliary atresia requires prompt surgical intervention (Kasai procedure) before 8 weeks to prevent cirrhosis. (Nelson)'),
    (v_topic_id, '33: What imaging modality is considered the best initial test when evaluating a neonate for suspected biliary atresia?",', '["Abdominal X-ray", "Abdominal Ultrasound", "HIDA scan", "MRI of the abdomen"]', 1, 'Ultrasound rules out other causes (choledochal cyst) and may show the "triangular cord sign" (fibrotic remnant of the biliary tree). (Case Files)'),
    (v_topic_id, '34: What is the gold standard diagnostic test for biliary atresia?",', '["HIDA scan showing lack of excretion into the bowel", "Liver biopsy showing bile duct proliferation and portal tract edema/fibrosis", "Intraoperative cholangiogram", "Elevated direct bilirubin levels"]', 2, 'Intraoperative cholangiogram definitively confirms the absence of a patent extrahepatic biliary tree, and is followed immediately by the Kasai portoenterostomy. (UWorld)'),
    (v_topic_id, '35: A full-term infant is born to a mother with gestational diabetes. The infant is macrosomic (4.5 kg). Two hours after birth, the infant becomes jittery and lethargic. What is the most likely diagnosis?",', '["Hypocalcemia", "Neonatal sepsis", "Neonatal hypoglycemia", "Polycythemia"]', 2, 'Infants of diabetic mothers (IDM) have fetal hyperinsulinemia due to maternal hyperglycemia. Once the maternal glucose supply is cut at birth, the persistent hyperinsulinemia rapidly drops their blood sugar. (First Aid)'),
    (v_topic_id, '36: In addition to hypoglycemia, infants of diabetic mothers are at increased risk for which of the following complications?",', '["Hypocalcemia, polycythemia, and hypertrophic cardiomyopathy", "Hypercalcemia, anemia, and dilated cardiomyopathy", "Hyponatremia, thrombocytopenia, and renal agenesis", "Hypernatremia, thrombocytosis, and pulmonary hypoplasia"]', 0, 'Hypocalcemia (delayed PTH surge), polycythemia (chronic fetal hypoxia driving EPO), and hypertrophic cardiomyopathy (insulin acts as a growth factor on the myocardium) are classic IDM complications. (Nelson)'),
    (v_topic_id, '37: An asymptomatic term infant has a bedside blood glucose of 35 mg/dL at 2 hours of life. What is the most appropriate first step in management?",', '["Administer IV 10% dextrose (D10W) bolus", "Feed the infant immediately (breast milk or formula) and recheck glucose in 30-60 minutes", "Administer IM glucagon", "Observe and recheck in 4 hours"]', 1, 'For asymptomatic mild hypoglycemia, enteral feeding is the first-line intervention. IV glucose is reserved for symptomatic hypoglycemia or severe/refractory cases. (Amboss)'),
    (v_topic_id, '38: A newborn presents with jitteriness, irritability, a high-pitched cry, tremors, and poor feeding at 48 hours of life. The mother received limited prenatal care. What is the most likely diagnosis?",', '["Hypoxic-ischemic encephalopathy", "Neonatal Abstinence Syndrome (NAS) / Opiate withdrawal", "Fetal alcohol syndrome", "Congenital syphilis"]', 1, 'Classic signs of NAS (withdrawal from maternal opiates/heroin/methadone). Symptoms typically appear between 24 and 72 hours of life. (Case Files)'),
    (v_topic_id, '39: What is the preferred pharmacological treatment for a neonate with severe Neonatal Abstinence Syndrome (NAS) that is not controlled with non-pharmacologic care (swaddling, dark room, high-calorie feeds)?",', '["Phenobarbital", "Morphine or Methadone", "Diazepam", "Naloxone"]', 1, 'Opiate replacement (morphine or methadone) is used to control severe symptoms, followed by a slow taper. (Nelson)'),
    (v_topic_id, '40: Why is Naloxone (Narcan) contraindicated in the delivery room for an infant born to a mother who is a chronic opiate abuser?",', '["It is ineffective in neonates", "It can precipitate acute, severe, and potentially life-threatening neonatal withdrawal (seizures)", "It causes respiratory depression", "It causes profound hypoglycemia"]', 1, 'Naloxone causes abrupt withdrawal. The treatment for apnea in any neonate, regardless of maternal drug history, is positive pressure ventilation. (NRP Guidelines)'),
    (v_topic_id, '41: A 2-day-old infant develops lethargy, poor feeding, temperature instability (hypothermia), and tachypnea. What is the most important initial step in management?",', '["Obtain blood, urine, and CSF cultures, then start empiric IV Ampicillin and Gentamicin", "Administer a fluid bolus and observe", "Start oral Amoxicillin", "Order a chest X-ray and await results before treating"]', 0, 'These are non-specific but classic signs of neonatal sepsis. A full sepsis evaluation and immediate empiric antibiotics are critical, as deterioration can be rapid. (UWorld)'),
    (v_topic_id, '42: What are the three most common organisms causing early-onset neonatal sepsis (within the first 72 hours of life)?",', '["Staphylococcus aureus, Pseudomonas, Candida", "Group B Streptococcus (GBS), E. coli, Listeria monocytogenes", "Streptococcus pneumoniae, Neisseria meningitidis, Haemophilus influenzae", "Klebsiella, Enterobacter, Serratia"]', 1, 'GBS is #1, followed closely by E. coli, then Listeria. (First Aid)'),
    (v_topic_id, '43: A mother is known to be GBS positive but delivered rapidly before receiving intrapartum antibiotic prophylaxis. Her term infant appears healthy and vigorous at birth. What is the appropriate management for the infant?",', '["Immediate full sepsis workup and antibiotics", "Close observation in the hospital for 48 hours", "Administer one dose of IM Penicillin G and discharge", "Discharge home immediately"]', 1, 'If the infant is well-appearing and term, the AAP recommends close observation for 48 hours. Routine labs and empiric antibiotics are not required unless the infant becomes symptomatic. (AAP Guidelines)'),
    (v_topic_id, '44: A neonate presents with a vesicular rash on the scalp, lethargy, and seizures at 10 days of life. The mother had no active lesions at delivery but a history of genital sores. What is the diagnosis and appropriate empiric treatment?",', '["Neonatal Varicella; Acyclovir", "Neonatal Herpes Simplex Virus (HSV); IV Acyclovir", "Congenital Syphilis; IV Penicillin G", "Staphylococcal Scalded Skin Syndrome; IV Oxacillin"]', 1, 'Neonatal HSV can present as Skin/Eye/Mouth (SEM) disease, CNS disease (seizures, encephalitis), or disseminated disease. Immediate IV Acyclovir is life-saving. (Nelson)'),
    (v_topic_id, '45: A newborn is small for gestational age and has microcephaly, cataracts, a continuous machinery murmur (PDA), and sensorineural hearing loss. Which congenital TORCH infection is most likely?",', '["Congenital Cytomegalovirus (CMV)", "Congenital Rubella Syndrome", "Congenital Toxoplasmosis", "Congenital Syphilis"]', 1, 'Classic triad of Congenital Rubella: Cataracts, Hearing loss, and Heart defects (PDA). (First Aid)'),
    (v_topic_id, '46: A newborn presents with hydrocephalus, diffuse intracranial calcifications, and chorioretinitis. The mother owns a cat and frequently gardens. What is the diagnosis?",', '["Congenital Cytomegalovirus (CMV)", "Congenital Rubella", "Congenital Toxoplasmosis", "Congenital Syphilis"]', 2, 'Classic triad of Toxoplasmosis: Chorioretinitis, Hydrocephalus, and Intracranial (often diffuse/parenchymal) calcifications. Transmitted via cat feces or undercooked meat. (Case Files)'),
    (v_topic_id, '47: What is the most common congenital viral infection in the developed world, often presenting with periventricular calcifications, microcephaly, and sensorineural hearing loss?",', '["Cytomegalovirus (CMV)", "Rubella", "Herpes Simplex Virus (HSV)", "Parvovirus B19"]', 0, 'CMV classically causes PERIVENTRICULAR calcifications (unlike toxo, which is diffuse) and is the leading cause of non-hereditary sensorineural hearing loss. (UWorld)'),
    (v_topic_id, '48: A newborn presents with a maculopapular rash on the palms and soles, "snuffles" (copious rhinorrhea), hepatosplenomegaly, and metaphyseal lucencies on long bone X-rays. What is the diagnosis?",', '["Congenital Syphilis", "Congenital Rubella", "Neonatal Lupus", "Erythema Toxicum Neonatorum"]', 0, 'Classic early signs of congenital syphilis. If untreated, progresses to late signs (Hutchinson teeth, saber shins, saddle nose). (Nelson)'),
    (v_topic_id, '49: What is the treatment for proven Congenital Syphilis in a neonate?",', '["IV Acyclovir for 14 days", "A single dose of IM Benzathine Penicillin G", "10 days of IV Ampicillin", "10 days of IV Aqueous Crystalline Penicillin G"]', 3, 'Proven congenital syphilis requires a 10-day course of IV aqueous crystalline penicillin G. (CDC Guidelines)'),
    (v_topic_id, '50: A neonate develops conjunctivitis at 3 days of life. There is copious, thick, purulent discharge and severe eyelid swelling. Gram stain shows gram-negative intracellular diplococci. Diagnosis and treatment?",', '["Chlamydia trachomatis; Oral Erythromycin", "Neisseria gonorrhoeae; A single dose of IM/IV Ceftriaxone or Cefotaxime", "Chemical conjunctivitis; Observation", "Adenovirus; Supportive care"]', 1, 'Gonococcal ophthalmia neonatorum occurs early (2-5 days) and is rapidly destructive to the cornea. Requires urgent systemic antibiotics. (Amboss)'),
    (v_topic_id, '51: A neonate develops conjunctivitis at 10 days of life with mild to moderate watery/mucopurulent discharge. What is the most likely etiology and what systemic complication must you monitor for?",', '["Neisseria gonorrhoeae; Sepsis", "Chlamydia trachomatis; Pneumonia (staccato cough)", "Herpes Simplex Virus; Encephalitis", "Staphylococcus aureus; Cellulitis"]', 1, 'Chlamydial conjunctivitis occurs later (5-14 days). It is treated with oral macrolides (erythromycin or azithromycin) to eradicate nasopharyngeal colonization and prevent Chlamydia pneumonia, which presents with a "staccato" cough. (Case Files)'),
    (v_topic_id, '52: Why is routine erythromycin ophthalmic ointment applied to all newborns immediately after birth?",', '["To prevent Chlamydia conjunctivitis", "To prevent Gonococcal ophthalmia neonatorum", "To prevent Herpes keratitis", "To prevent congenital cataracts"]', 1, 'Prophylactic eye ointment is highly effective at preventing Gonococcal conjunctivitis, but it does NOT effectively prevent Chlamydial conjunctivitis. (AAP)'),
    (v_topic_id, '53: A 3-day-old premature infant (28 weeks) develops temperature instability, abdominal distension, bloody stools, and bilious emesis. Abdominal X-ray shows pneumatosis intestinalis. What is the most likely diagnosis?",', '["Intussusception", "Malrotation with midgut volvulus", "Necrotizing Enterocolitis (NEC)", "Hirschsprung disease"]', 2, 'Pneumatosis intestinalis (air in the bowel wall) is the pathognomonic X-ray finding for NEC. It primarily affects premature infants once enteral feeding has begun. (Nelson)'),
    (v_topic_id, '54: What is the initial medical management for Necrotizing Enterocolitis (NEC)?",', '["Immediate exploratory laparotomy", "Barium enema", "NPO, gastric decompression (NG tube), IV fluids, and broad-spectrum IV antibiotics", "Oral vancomycin"]', 2, 'Initial management is strict bowel rest (NPO) and systemic antibiotics. Surgery is indicated if there is pneumoperitoneum (perforation) or failure of medical management. (UWorld)'),
    (v_topic_id, '55: A 1-day-old infant presents with bilious emesis. Abdominal X-ray shows a "double bubble" sign with no distal gas. The infant also has upslanting palpebral fissures, a single palmar crease, and hypotonia. What is the GI diagnosis?",', '["Duodenal Atresia", "Jejunal Atresia", "Pyloric Stenosis", "Meconium Ileus"]', 0, 'Duodenal atresia presents with the "double bubble" sign (stomach and proximal duodenum) and is highly associated with Down syndrome (Trisomy 21). (First Aid)'),
    (v_topic_id, '56: A newborn fails to pass meconium within the first 48 hours of life. They develop abdominal distension and bilious emesis. Contrast enema shows a "microcolon" and inspissated, pellet-like meconium in the terminal ileum. What is the underlying genetic disease?",', '["Down syndrome", "Cystic Fibrosis", "Hirschsprung disease", "Sickle cell anemia"]', 1, 'This is Meconium Ileus, which is almost exclusively seen in patients with Cystic Fibrosis due to thick, viscous secretions. (Case Files)'),
    (v_topic_id, '57: A full-term newborn fails to pass meconium in the first 48 hours. Digital rectal exam reveals a tight anal sphincter, followed by an explosive release of gas and stool (squirt sign). What is the diagnosis?",', '["Meconium Ileus", "Hirschsprung disease", "Imperforate anus", "Volvulus"]', 1, 'Hirschsprung disease (congenital aganglionic megacolon) involves the absence of ganglion cells in the distal colon, causing failure of relaxation. The "squirt sign" is classic. (Amboss)'),
    (v_topic_id, '58: What is the gold standard diagnostic test to confirm Hirschsprung disease?",', '["Contrast enema", "Abdominal X-ray", "Rectal suction biopsy", "Anorectal manometry"]', 2, 'Rectal suction biopsy confirms the absence of ganglion cells in the submucosal (Meissner) and myenteric (Auerbach) plexuses. (Nelson)'),
    (v_topic_id, '59: A 1-month-old infant presents with projectile, non-bilious emesis immediately after every feeding. The infant is hungry and feeds eagerly. Physical exam reveals a firm, olive-shaped mass in the right upper quadrant. What acid-base derangement is expected?",', '["Hyperchloremic metabolic acidosis", "Hypochloremic, hypokalemic metabolic alkalosis", "Respiratory acidosis", "Metabolic acidosis with elevated anion gap"]', 1, 'Pyloric stenosis causes massive loss of gastric acid (HCl). The kidneys compensate by retaining H+ and excreting K+, leading to hypokalemic, hypochloremic metabolic alkalosis. (UWorld)'),
    (v_topic_id, '60: A neonate presents with sudden onset of bilious emesis and hemodynamic instability. Abdominal X-ray is non-specific, but an upper GI series shows the duodenojejunal junction on the right side of the spine and a "corkscrew" appearance of the duodenum. Diagnosis?",', '["Pyloric stenosis", "Intussusception", "Malrotation with midgut volvulus", "Duodenal atresia"]', 2, 'Malrotation with midgut volvulus is a surgical emergency. The bowel twists on its mesenteric axis, causing ischemia and necrosis. (Case Files)'),
    (v_topic_id, '61: A newborn is noted to have a swelling over the right parietal bone that does NOT cross the sagittal suture line. The swelling appeared several hours after a vacuum-assisted delivery. Diagnosis?",', '["Caput succedaneum", "Cephalohematoma", "Subgaleal hemorrhage", "Encephalocele"]', 1, 'A cephalohematoma is a subperiosteal hemorrhage, thus it is bounded by the periosteal attachments at the suture lines and DOES NOT cross them. (Nelson)'),
    (v_topic_id, '62: A newborn is noted to have diffuse scalp swelling immediately after a prolonged vaginal delivery. The swelling CROSSES suture lines and feels boggy. Diagnosis?",', '["Cephalohematoma", "Caput succedaneum", "Epidural hematoma", "Skull fracture"]', 1, 'Caput succedaneum is subcutaneous edema of the scalp that crosses suture lines. It is benign and resolves in a few days. (Amboss)'),
    (v_topic_id, '63: A newborn presents with rapidly expanding scalp swelling that crosses suture lines, pushing the ears forward. The infant becomes tachycardic, hypotensive, and pale. Diagnosis?",', '["Caput succedaneum", "Cephalohematoma", "Subgaleal hemorrhage", "Normal molding"]', 2, 'Subgaleal hemorrhage occurs between the epicranial aponeurosis and periosteum. It is a massive potential space; the infant can bleed their entire blood volume into it, causing hypovolemic shock. (UWorld)'),
    (v_topic_id, '64: Following a difficult shoulder dystocia delivery, a neonate''s right arm is adducted, internally rotated, with the elbow extended and forearm pronated (waiter''s tip posture). The grasp reflex is intact. What is the injured structure?",', '["Upper brachial plexus (C5-C6) - Erb-Duchenne palsy", "Lower brachial plexus (C8-T1) - Klumpke palsy", "Clavicle fracture", "Radial nerve"]', 0, 'Erb palsy affects the upper trunk. "Waiter''s tip" is classic. The grasp reflex is preserved because the lower trunk (C8-T1) is intact. (First Aid)'),
    (v_topic_id, '65: Following a breech delivery where the arm was hyperabducted, a neonate presents with an absent grasp reflex in the left hand and a claw-hand deformity. What is the injured structure and what associated physical finding might be present?",', '["Upper brachial plexus; Phrenic nerve palsy", "Lower brachial plexus (C8-T1) - Klumpke palsy; Horner syndrome", "Median nerve; Carpal tunnel", "Axillary nerve; Deltoid atrophy"]', 1, 'Klumpke palsy affects the lower trunk, causing intrinsic hand muscle weakness. It may be accompanied by Horner syndrome (ptosis, miosis, anhidrosis) if the T1 sympathetic fibers are torn. (Case Files)'),
    (v_topic_id, '66: A newborn is noted to have an asymmetric Moro reflex and crepitus over the right collarbone following a large-for-gestational-age delivery. Grasp reflex is intact. Diagnosis?",', '["Erb palsy", "Clavicle fracture", "Humerus fracture", "Klumpke palsy"]', 1, 'Clavicle fracture is the most common fracture during delivery. Management is supportive (pinning the sleeve to the shirt to immobilize). (Nelson)'),
    (v_topic_id, '67: An infant born at 26 weeks gestation undergoes a routine cranial ultrasound at 1 week of life. It reveals bleeding within the germinal matrix that extends into the lateral ventricles, causing ventricular dilation. What is the diagnosis?",', '["Grade I Intraventricular Hemorrhage (IVH)", "Grade II IVH", "Grade III IVH", "Grade IV IVH"]', 2, 'Grade I: Germinal matrix only. Grade II: IVH without ventricular dilation. Grade III: IVH WITH ventricular dilation. Grade IV: Parenchymal extension. (Amboss)'),
    (v_topic_id, '68: What is the most significant risk factor for Intraventricular Hemorrhage (IVH) in a neonate?",', '["Maternal diabetes", "Prematurity (especially < 30 weeks)", "Post-term delivery", "Forceps delivery"]', 1, 'The germinal matrix is a highly vascular, fragile area in the premature brain that is prone to bleeding with fluctuations in cerebral blood flow. It involutes by 32-34 weeks. (UWorld)'),
    (v_topic_id, '69: A premature infant (25 weeks) is placed on supplemental oxygen for 6 weeks. The infant is at high risk for developing which of the following ophthalmologic conditions?",', '["Congenital glaucoma", "Retinoblastoma", "Retinopathy of Prematurity (ROP)", "Cataracts"]', 2, 'ROP is abnormal neovascularization of the retina triggered by hyperoxia and subsequent hypoxia. It can lead to retinal detachment and blindness. (First Aid)'),
    (v_topic_id, '70: A newborn male has the urethral meatus located on the ventral (underside) surface of the penis. What is the diagnosis and what common neonatal procedure is CONTRAINDICATED?",', '["Epispadias; Circumcision", "Hypospadias; Circumcision", "Phimosis; Catheterization", "Cryptorchidism; Ultrasound"]', 1, 'Hypospadias results from failure of the urethral folds to close. Circumcision is contraindicated because the prepuce (foreskin) is used later for surgical repair. (Case Files)'),
    (v_topic_id, '71: A term infant presents with plethora (ruddy, red skin), lethargy, jitteriness, and hypoglycemia. A peripheral venous hematocrit is checked and returns at 70%. Diagnosis?",', '["Neonatal anemia", "Neonatal sepsis", "Neonatal Polycythemia", "Cyanotic heart disease"]', 2, 'Neonatal polycythemia is defined as a venous Hct > 65%. It causes hyperviscosity, leading to sluggish blood flow, tissue hypoxia, and consumption of glucose. (Nelson)'),
    (v_topic_id, '72: What is the appropriate treatment for symptomatic neonatal polycythemia (e.g., lethargy, respiratory distress)?",', '["Blood transfusion", "Partial exchange transfusion (replacing a portion of the blood volume with normal saline)", "IV iron therapy", "Erythropoietin administration"]', 1, 'Partial exchange transfusion dilutes the red blood cell mass, lowering the hematocrit and decreasing blood viscosity without altering the total blood volume. (UWorld)'),
    (v_topic_id, '73: A newborn presents with profound cyanosis within hours of birth. The cyanosis does NOT improve with the administration of 100% oxygen (failed hyperoxia test). Chest X-ray shows an "egg on a string" appearance of the heart. What is the most likely diagnosis?",', '["Tetralogy of Fallot", "Transposition of the Great Arteries (TGA)", "Truncus Arteriosus", "Total Anomalous Pulmonary Venous Return"]', 1, 'TGA is the most common cyanotic congenital heart defect presenting in the FIRST FEW DAYS of life. The aorta and pulmonary artery are switched, creating two parallel circuits. It requires an intracardiac shunt (VSD, PDA, PFO) to survive. (Amboss)'),
    (v_topic_id, '74: What life-saving medication must be initiated immediately in a neonate with Transposition of the Great Arteries while awaiting surgical repair?",', '["Indomethacin", "Ibuprofen", "Prostaglandin E1 (Alprostadil)", "Epinephrine"]', 2, 'Prostaglandin E1 keeps the ductus arteriosus patent, allowing mixing of oxygenated and deoxygenated blood between the two parallel circuits. (First Aid)'),
    (v_topic_id, '75: A neonate presents with cyanosis and a harsh systolic ejection murmur at the left upper sternal border. Chest X-ray shows a "boot-shaped heart." What is the diagnosis?",', '["Tetralogy of Fallot (ToF)", "Tricuspid Atresia", "Ebstein Anomaly", "Coarctation of the Aorta"]', 0, 'ToF includes VSD, overriding aorta, pulmonary stenosis, and right ventricular hypertrophy (causing the boot shape). It is the most common cyanotic heart defect overall, but often presents slightly later than TGA. (Case Files)'),
    (v_topic_id, '76: A newborn appears healthy at birth but develops sudden, profound shock, metabolic acidosis, and absent femoral pulses on day 3 of life as the ductus arteriosus closes. Diagnosis?",', '["Severe Coarctation of the Aorta or Hypoplastic Left Heart Syndrome", "Atrial Septal Defect", "Patent Ductus Arteriosus", "Ventricular Septal Defect"]', 0, 'These are ductal-dependent systemic lesions. When the PDA closes, systemic perfusion abruptly ceases, leading to cardiogenic shock. Treat with PGE1. (Nelson)'),
    (v_topic_id, '77: A premature infant (26 weeks) develops a continuous "machine-like" murmur at the left infraclavicular area, bounding peripheral pulses, and a widened pulse pressure. Diagnosis?",', '["Ventricular Septal Defect", "Atrial Septal Defect", "Patent Ductus Arteriosus (PDA)", "Coarctation of the Aorta"]', 2, 'Prematurity is a major risk factor for failure of the ductus arteriosus to close. The murmur is continuous because aortic pressure is higher than pulmonary pressure in both systole and diastole. (UWorld)'),
    (v_topic_id, '78: What is the initial medical treatment to close a symptomatic Patent Ductus Arteriosus (PDA) in a premature infant?",', '["Prostaglandin E1", "Cyclooxygenase (COX) inhibitors like Indomethacin or Ibuprofen", "Beta-blockers", "Surgical ligation is the only option"]', 1, 'Prostaglandins keep the PDA open. COX inhibitors block prostaglandin synthesis, promoting closure of the ductus. (Amboss)'),
    (v_topic_id, '79: A 2-day-old infant presents with a blotchy, erythematous rash with central yellow/white papules containing eosinophils. It is scattered over the trunk and extremities but spares the palms and soles. The infant is otherwise completely asymptomatic. Diagnosis?",', '["Erythema Toxicum Neonatorum", "Neonatal Herpes Simplex", "Staphylococcal Pustulosis", "Milia"]', 0, 'Erythema toxicum is a benign, self-limiting rash appearing in 50% of term newborns within the first few days of life. Requires no treatment. (Case Files)'),
    (v_topic_id, '80: A newborn presents with tiny, pinpoint white papules on the nose and cheeks. They consist of keratin-filled epithelial cysts. Diagnosis?",', '["Neonatal acne", "Milia", "Sebaceous hyperplasia", "Mongolian spots"]', 1, 'Milia are benign and spontaneously resolve in the first few weeks of life. (First Aid)'),
    (v_topic_id, '81: A newborn of African descent presents with large, flat, blue-gray macular patches over the sacrum and buttocks. What is the appropriate management?",', '["Report to child protective services for suspected bruising", "Biopsy to rule out melanoma", "Reassure parents; these are benign congenital dermal melanocytoses (formerly Mongolian spots) that will fade over years", "Laser therapy"]', 2, 'These are extremely common, benign birthmarks caused by delayed disappearance of dermal melanocytes. It is vital to document them to avoid later confusion with child abuse bruises. (Nelson)'),
    (v_topic_id, '82: A newborn is noted to have a bright red, sharply demarcated, raised, soft lobulated plaque on the scalp. It was barely visible at birth but grew rapidly over the first few weeks. Diagnosis?",', '["Nevus simplex (Stork bite)", "Port-wine stain (Nevus flammeus)", "Infantile Hemangioma (Strawberry hemangioma)", "Melanocytic nevus"]', 2, 'Infantile hemangiomas grow rapidly in the first year and then slowly involute over 5-10 years. (Amboss)'),
    (v_topic_id, '83: What is the first-line medical treatment for an infantile hemangioma that is threatening the visual axis (e.g., growing over the eyelid)?",', '["Topical steroids", "Oral propranolol", "Surgical excision", "Observation"]', 1, 'Oral beta-blockers (propranolol) induce vasoconstriction and promote regression of problematic hemangiomas. (UWorld)'),
    (v_topic_id, '84: A newborn has a large, flat, dark red/purple patch over the right side of their face, distributed in the V1/V2 distribution of the trigeminal nerve. The lesion does not regress over time. What syndrome must be considered?",', '["Sturge-Weber Syndrome", "Neurofibromatosis type 1", "Tuberous Sclerosis", "Klippel-Trenaunay Syndrome"]', 0, 'A port-wine stain in the trigeminal distribution is highly associated with Sturge-Weber syndrome, which includes ipsilateral leptomeningeal angiomas, seizures, and glaucoma. (Case Files)'),
    (v_topic_id, '85: A neonate is born with ambiguous genitalia. Labs reveal hyponatremia, hyperkalemia, hypoglycemia, and metabolic acidosis. What is the most likely underlying diagnosis?",', '["Turner Syndrome", "Congenital Adrenal Hyperplasia (CAH), specifically 21-hydroxylase deficiency", "Complete Androgen Insensitivity Syndrome", "Klinefelter Syndrome"]', 1, '21-hydroxylase deficiency prevents the synthesis of cortisol and aldosterone, shunting precursors to androgens (virilization of female). Lack of aldosterone causes salt-wasting (low Na, high K, low BP). (Nelson)'),
    (v_topic_id, '86: What screening test is included in all US newborn screens to detect Congenital Adrenal Hyperplasia before a salt-wasting crisis occurs?",', '["17-hydroxyprogesterone (17-OHP) levels", "Cortisol levels", "Aldosterone levels", "Testosterone levels"]', 0, '17-OHP is the precursor immediately prior to the 21-hydroxylase enzyme. In CAH, it builds up to very high levels. (First Aid)'),
    (v_topic_id, '87: A newborn screen returns positive for PKU (Phenylketonuria). What enzyme is deficient, and what is the primary clinical consequence if untreated?",', '["Galactose-1-phosphate uridyltransferase; Liver failure", "Phenylalanine hydroxylase; Severe intellectual disability and seizures", "Alpha-glucosidase; Heart failure", "Glucose-6-phosphatase; Severe hypoglycemia"]', 1, 'PKU patients cannot convert phenylalanine to tyrosine. Phenylalanine accumulates in the brain causing severe intellectual disability. Treatment is a lifelong phenylalanine-restricted diet. (Amboss)'),
    (v_topic_id, '88: A neonate presents with jaundice, hepatomegaly, vomiting, and E. coli sepsis after the initiation of formula or breast milk. Newborn screen is pending. What is the most likely metabolic diagnosis?",', '["Phenylketonuria", "Classic Galactosemia", "Glycogen Storage Disease Type I", "Medium-chain acyl-CoA dehydrogenase (MCAD) deficiency"]', 1, 'Classic galactosemia (GALT deficiency) presents rapidly after lactose ingestion (breast milk/standard formula). It strongly predisposes to E. coli sepsis. (UWorld)'),
    (v_topic_id, '89: What is the dietary management for a neonate diagnosed with Classic Galactosemia?",', '["Low phenylalanine diet", "Switch from breast milk to a soy-based, lactose-free formula", "High-protein diet", "MCT oil supplementation"]', 1, 'Lactose is composed of glucose and galactose. Therefore, ALL lactose (including breast milk) is strictly contraindicated. Soy formula is required. (Case Files)'),
    (v_topic_id, '90: A newborn presents with a sacral dimple with a small tuft of hair over it. What underlying congenital anomaly must be evaluated?",', '["Meningomyelocele", "Spina bifida occulta / Tethered spinal cord", "Sacrococcygeal teratoma", "Anencephaly"]', 1, 'A sacral hair tuft, deep dimple, or lipoma suggests spina bifida occulta. An ultrasound of the lumbar spine is indicated to rule out a tethered cord. (Nelson)'),
    (v_topic_id, '91: A newborn is diagnosed with an omphalocele. What distinguishes an omphalocele from gastroschisis?",', '["Omphalocele is a defect to the right of the umbilicus; gastroschisis is central", "Omphalocele is covered by a peritoneal/amniotic membrane and emerges from the umbilicus; gastroschisis is not covered by a membrane and is paraumbilical", "There is no difference", "Gastroschisis is highly associated with chromosomal anomalies, omphalocele is not"]', 1, 'Omphalocele = sealed (in a sac) and central (umbilical). Gastroschisis = open (no sac) and lateral (usually right of umbilicus). Omphalocele is highly associated with genetic syndromes (e.g., Trisomy 13, 18, Beckwith-Wiedemann). (First Aid)'),
    (v_topic_id, '92: A newborn is noted to have a very large tongue (macroglossia), macrosomia, an omphalocele, and profound hypoglycemia. What syndrome should be suspected?",', '["Down syndrome", "Beckwith-Wiedemann Syndrome", "Prader-Willi Syndrome", "Turner syndrome"]', 1, 'Beckwith-Wiedemann is an overgrowth syndrome. The hypoglycemia is due to hyperinsulinemia (pancreatic hyperplasia). These patients are at high risk for Wilms tumor and hepatoblastoma. (Amboss)'),
    (v_topic_id, '93: A neonate presents with failure to pass meconium, bilious emesis, and abdominal distension. A contrast enema shows a "transition zone" between a narrow, aganglionic distal colon and a dilated, normally innervated proximal colon. Diagnosis?",', '["Meconium plug syndrome", "Hirschsprung disease", "Volvulus", "Intussusception"]', 1, 'The transition zone on contrast enema is the classic radiological sign of Hirschsprung disease. (UWorld)'),
    (v_topic_id, '94: A term infant is delivered through meconium-stained fluid. The infant is vigorous, crying robustly, and has a heart rate of 140. What is the recommended management?",', '["Immediate endotracheal intubation and deep suctioning", "Routine care (warm, dry, stimulate, clear secretions from mouth/nose if needed)", "Administer prophylactic antibiotics", "Gastric lavage"]', 1, 'Current NRP guidelines state that if a meconium-stained infant is VIGOROUS, no routine intubation/suctioning is required. Routine care is sufficient. (NRP)'),
    (v_topic_id, '95: A term infant is delivered through meconium-stained fluid. The infant is limp, apneic, and has a heart rate of 80. What is the recommended immediate management?",', '["Intubate and suction the trachea", "Begin Positive Pressure Ventilation (PPV) immediately using a bag-mask device", "Start chest compressions", "Give IV epinephrine"]', 1, 'NRP guidelines have changed. Routine endotracheal suctioning for non-vigorous infants with meconium is NO LONGER recommended. The priority is establishing ventilation; start PPV immediately. (NRP 2020 Guidelines)'),
    (v_topic_id, '96: During a routine exam of a 1-day-old infant, the pediatrician flexes the infant''s hips and knees to 90 degrees, then abducts the hips while applying anterior pressure to the greater trochanter. A "clunk" is felt. What is this maneuver called and what does it signify?",', '["Barlow maneuver; dislocates the hip", "Ortolani maneuver; reduces a dislocated hip (Developmental Dysplasia of the Hip)", "Galeazzi sign; leg length discrepancy", "Trendelenburg test; gluteus medius weakness"]', 1, 'Ortolani = "Out to In" (reduces the hip). Barlow = "Back and Out" (dislocates the hip). A positive Ortolani clunk diagnoses DDH. (Case Files)'),
    (v_topic_id, '97: A 2-week-old female infant presents with a small amount of bloody vaginal discharge. The infant is otherwise completely normal. What is the cause and management?",', '["Sexual abuse; report immediately", "Neonatal withdrawal bleeding due to maternal estrogen withdrawal; reassure parents", "Coagulopathy; order PT/PTT", "Vaginal tumor; order ultrasound"]', 1, 'This is a normal, self-limiting phenomenon caused by the sudden drop in maternal estrogens after birth, leading to mild endometrial sloughing. (Nelson)'),
    (v_topic_id, '98: A neonate presents with a webbed neck, widespread nipples, lymphedema of the hands and feet, and a horseshoe kidney. Which congenital heart defect is most strongly associated with this genetic syndrome?",', '["Bicuspid aortic valve and Coarctation of the aorta", "Atrioventricular septal defect (AV canal)", "Tetralogy of Fallot", "Ebstein anomaly"]', 0, 'This is Turner syndrome (45,XO). They are at high risk for left-sided heart lesions, most notably bicuspid aortic valve and coarctation of the aorta. (First Aid)'),
    (v_topic_id, '99: A neonate is born with Trisomy 21 (Down syndrome). Which congenital heart defect is most strongly associated with this syndrome?",', '["Coarctation of the aorta", "Endocardial cushion defect (Complete Atrioventricular Septal Defect)", "Transposition of the Great Arteries", "Truncus Arteriosus"]', 1, 'AV septal defects (AV canal defects) are the classic cardiac anomaly in Down syndrome. (UWorld)'),
    (v_topic_id, '100: A newborn presents with micrognathia (small jaw), glossoptosis (tongue falls back into airway), and a U-shaped cleft palate. They have severe respiratory distress in the supine position. Diagnosis?",', '["Pierre Robin Sequence", "Treacher Collins Syndrome", "DiGeorge Syndrome", "Crouzon Syndrome"]', 0, 'Pierre Robin sequence is a cascade of events: the small jaw prevents the tongue from descending, which prevents the palate shelves from fusing, leading to airway obstruction. (Amboss)'),
    (v_topic_id, '101: A newborn with Pierre Robin sequence presents with acute respiratory distress and cyanosis when lying supine. What is the most appropriate initial management?",', '["Place the infant in the prone position", "Perform an emergency tracheostomy", "Administer inhaled racemic epinephrine", "Start positive pressure ventilation via bag-mask"]', 0, 'Placing the infant prone allows gravity to pull the tongue forward, relieving the airway obstruction caused by glossoptosis. (Nelson)'),
    (v_topic_id, '102: A neonate presents with a scaphoid abdomen, respiratory distress, and dextrocardia. A chest X-ray confirms loops of bowel in the left hemithorax. What is the most critical embryologic failure leading to this defect?",', '["Failure of the pleuroperitoneal membrane to close", "Failure of the tracheoesophageal septum to partition", "Failure of the midgut to return to the abdominal cavity", "Failure of the vitelline duct to obliterate"]', 0, 'A Bochdalek hernia (the most common type of Congenital Diaphragmatic Hernia) is due to failure of the posterolateral pleuroperitoneal membrane to close. (First Aid)'),
    (v_topic_id, '103: A neonate with severe respiratory distress syndrome is placed on a mechanical ventilator. Several hours later, the infant abruptly develops severe cyanosis, bradycardia, and asymmetric chest rise with diminished breath sounds on the right. What life-threatening complication has occurred?",', '["Tension pneumothorax", "Displaced endotracheal tube into the right mainstem bronchus", "Pulmonary hemorrhage", "Equipment failure"]', 0, 'Sudden deterioration with asymmetric breath sounds in a ventilated neonate is a tension pneumothorax until proven otherwise. Treat with immediate needle decompression. (NRP)'),
    (v_topic_id, '104: Transillumination of the chest with a high-intensity fiberoptic light is a rapid bedside test used in neonatology primarily to detect what condition?",', '["Pneumothorax", "Pleural effusion", "Congenital diaphragmatic hernia", "Pneumonia"]', 0, 'A large pocket of air in the pleural space (pneumothorax) will brightly transilluminate, whereas normal lung tissue diffuses the light. (Case Files)'),
    (v_topic_id, '105: An infant is born via vacuum extraction and develops a rapidly enlarging, firm swelling over the right parietal bone hours later. It does not cross the sagittal suture. The infant becomes jaundiced on day 3. What is the relationship between the swelling and the jaundice?",', '["The swelling indicates a cephalohematoma; breakdown of the trapped RBCs leads to an increased unconjugated bilirubin load", "The vacuum caused liver damage leading to jaundice", "The swelling is a caput succedaneum, which directly causes hemolysis", "There is no relationship"]', 0, 'A cephalohematoma is a sequestered collection of blood. As the macrophages break down these RBCs, the bilirubin load overwhelms the immature liver, causing significant jaundice. (Nelson)'),
    (v_topic_id, '106: A full-term neonate is noted to have a palpable, olive-sized mass in the sternocleidomastoid muscle and the head is tilted toward the mass with the chin rotated away. What is the diagnosis?",', '["Congenital muscular torticollis", "Cervical lymphadenitis", "Thyroglossal duct cyst", "Branchial cleft cyst"]', 0, 'Often due to intrauterine positioning or birth trauma (fibromatosis colli). Managed with physical therapy (stretching exercises). (UWorld)'),
    (v_topic_id, '107: A 3-week-old infant, born at 28 weeks gestation, presents with apneic episodes, bradycardia, and temperature instability. They had been tolerating feeds well until today. Abdominal exam is benign. What is the most appropriate next step?",', '["Perform a full sepsis evaluation and start empiric antibiotics", "Increase the environmental temperature in the incubator", "Start oral caffeine therapy for apnea of prematurity", "Obtain an abdominal X-ray to rule out NEC"]', 0, 'Any new-onset apnea, bradycardia, or temperature instability in a neonate (even if premature) must be considered sepsis until proven otherwise. (Amboss)'),
    (v_topic_id, '108: Apnea of prematurity is common in infants born < 34 weeks gestation. What medication is the standard of care to stimulate the central respiratory drive and reduce apneic events?",', '["Caffeine citrate", "Theophylline", "Dexamethasone", "Albuterol"]', 0, 'Caffeine citrate acts as an adenosine antagonist in the CNS, stimulating the respiratory center. It has a wider therapeutic index and fewer side effects than theophylline. (Nelson)'),
    (v_topic_id, '109: What is the definition of apnea in a neonate?",', '["Cessation of breathing for > 20 seconds, OR any pause in breathing accompanied by bradycardia or cyanosis", "Cessation of breathing for > 10 seconds", "Periodic breathing with 5-second pauses", "Respiratory rate less than 30 breaths per minute"]', 0, 'Periodic breathing (short pauses < 10 seconds followed by rapid breathing) is normal. True apnea is > 20 seconds or associated with physiologic compromise. (First Aid)'),
    (v_topic_id, '110: A neonate develops conjunctivitis at 2 days of life. Gram stain is negative, but the culture eventually grows a common skin flora. What chemical agent, previously used for prophylaxis, classically caused chemical conjunctivitis in the first 24 hours of life?",', '["Silver nitrate", "Erythromycin", "Povidone-iodine", "Tetracycline"]', 0, 'Silver nitrate drops frequently caused severe chemical conjunctivitis, which is why erythromycin ointment is now the standard of care. (Case Files)'),
    (v_topic_id, '111: A 1-day-old infant is found to have absent red reflexes bilaterally. The mother had a rash and lymphadenopathy during the first trimester. What is the most likely diagnosis?",', '["Congenital cataracts due to Rubella", "Retinoblastoma", "Congenital glaucoma", "CMV retinitis"]', 0, 'Congenital rubella is a classic cause of congenital cataracts (absent red reflex). (UWorld)'),
    (v_topic_id, '112: A neonate presents with tearing, photophobia, and an enlarged, cloudy cornea (buphthalmos) in the left eye. What is the diagnosis?",', '["Congenital glaucoma", "Dacryostenosis (blocked tear duct)", "Conjunctivitis", "Corneal abrasion"]', 0, 'Congenital glaucoma is caused by maldevelopment of the anterior chamber angle, leading to elevated intraocular pressure, corneal edema (cloudiness), and enlargement of the eye. Requires urgent ophthalmology referral. (Nelson)'),
    (v_topic_id, '113: A 4-week-old infant presents with continuous tearing and crusting of the right eye since birth. The conjunctiva is white and quiet (no redness). What is the most likely diagnosis?",', '["Congenital dacryostenosis (nasolacrimal duct obstruction)", "Neonatal conjunctivitis", "Congenital glaucoma", "Corneal ulcer"]', 0, 'Blocked tear duct is very common. The lack of conjunctival injection (redness) differentiates it from infectious conjunctivitis. Management is lacrimal sac massage. (Amboss)'),
    (v_topic_id, '114: A newborn male has an empty left scrotal sac. The testis cannot be palpated in the inguinal canal. What is the diagnosis and initial management?",', '["Cryptorchidism; Observe until 6 months of age", "Cryptorchidism; Immediate orchiopexy", "Ectopic testis; Order an MRI", "Retractile testis; Administer hCG"]', 0, 'Most undescended testes will spontaneously descend by 6 months. If not descended by 6 months, surgical orchiopexy is indicated to preserve fertility and reduce/monitor cancer risk. (Case Files)'),
    (v_topic_id, '115: What is the most serious long-term complication of untreated cryptorchidism?",', '["Testicular cancer (seminoma)", "Erectile dysfunction", "Testicular torsion", "Epididymitis"]', 0, 'The intra-abdominal temperature damages germ cells. Orchiopexy before age 1 improves fertility but does NOT eliminate the increased risk of testicular cancer, though it makes the testis palpable for monitoring. (First Aid)'),
    (v_topic_id, '116: A neonate is noted to have a cystic, fluid-filled mass in the right scrotum that transilluminates brightly. The mass does not change in size with crying. Diagnosis?",', '["Non-communicating hydrocele", "Communicating hydrocele", "Inguinal hernia", "Testicular torsion"]', 0, 'A non-communicating hydrocele is residual peritoneal fluid in the tunica vaginalis; the processus vaginalis is closed. It usually resolves spontaneously by age 1. (Nelson)'),
    (v_topic_id, '117: A neonate presents with a scrotal mass that transilluminates. However, the mother notes the mass gets much larger when the baby cries or strains. Diagnosis?",', '["Communicating hydrocele", "Non-communicating hydrocele", "Varicocele", "Spermatocele"]', 0, 'A communicating hydrocele means the processus vaginalis remains open, allowing peritoneal fluid to flow in and out. It carries a risk of developing an indirect inguinal hernia and often requires surgical closure. (UWorld)'),
    (v_topic_id, '118: A newborn infant develops severe cyanosis immediately after birth. Oxygen saturations are 60% on room air and only rise to 65% when placed on 100% FiO2. What does this failed hyperoxia test indicate?",', '["Right-to-left intracardiac or great vessel shunting (Cyanotic congenital heart disease)", "Severe pulmonary disease (e.g., RDS)", "Neurologic hypoventilation", "Methemoglobinemia"]', 0, 'A failed hyperoxia test (PaO2 fails to rise > 150 mmHg on 100% O2) suggests the deoxygenated blood is completely bypassing the lungs due to a fixed anatomic shunt. (Amboss)'),
    (v_topic_id, '119: What is the classic chest X-ray finding for Total Anomalous Pulmonary Venous Return (TAPVR) when it is supracardiac?",', '["Snowman sign (Figure of 8)", "Egg on a string", "Boot-shaped heart", "Wall-to-wall heart (massive cardiomegaly)"]', 0, 'The "snowman" is formed by the dilated vertical vein and superior vena cava stacked on top of the cardiac silhouette. (First Aid)'),
    (v_topic_id, '120: A neonate presents with severe cyanosis, a single S2, and a systolic murmur. ECG shows LEFT axis deviation and LEFT ventricular hypertrophy. Which cyanotic heart defect is characterized by LVH rather than the typical RVH?",', '["Tricuspid Atresia", "Tetralogy of Fallot", "Transposition of the Great Arteries", "Truncus Arteriosus"]', 0, 'In Tricuspid Atresia, blood cannot enter the right ventricle, so it shunts R->L across an ASD to the left ventricle. The LV must pump blood to both the systemic and pulmonary (via VSD/PDA) circuits, leading to LVH. The RV is hypoplastic. (Nelson)'),
    (v_topic_id, '121: A neonate is diagnosed with Ebstein anomaly. What maternal medication exposure during pregnancy is classically associated with this defect?",', '["Lithium", "Valproic acid", "Isotretinoin", "Phenytoin"]', 0, 'Lithium use during the first trimester is associated with Ebstein anomaly (downward displacement of the tricuspid valve leaflets into the right ventricle, causing "atrialization" of the RV and severe TR). (Case Files)'),
    (v_topic_id, '122: A newborn is noted to have a heart murmur. Echocardiogram reveals a small, restrictive Ventricular Septal Defect (VSD). What is the typical clinical course for this patient?",', '["Spontaneous closure in the majority of cases within the first few years of life", "Rapid development of heart failure requiring urgent surgery", "Development of Eisenmenger syndrome by age 2", "Requires immediate balloon atrial septostomy"]', 0, 'Small VSDs (which ironically have the loudest murmurs due to high turbulence) are usually asymptomatic and close spontaneously. (UWorld)'),
    (v_topic_id, '123: A 2-month-old infant presents with poor feeding, diaphoresis during feeds, failure to thrive, and a harsh holosystolic murmur. Echocardiogram shows a large VSD. Why did the infant not present with heart failure in the first week of life?",', '["Pulmonary vascular resistance is high at birth and drops over the first 4-8 weeks, gradually increasing the left-to-right shunt until heart failure occurs", "The VSD grew larger over time", "The right ventricle was initially strong enough to compensate", "Maternal antibodies protected the heart"]', 0, 'High neonatal PVR prevents a massive L->R shunt initially. As PVR drops, the shunt volume increases, leading to pulmonary overcirculation and congestive heart failure at 1-2 months of age. (Nelson)'),
    (v_topic_id, '124: A term infant is born cyanotic with a heart rate of 70 bpm and absent respiratory effort. What is the very first step in NRP?",', '["Provide warmth, position head, clear airway, dry, and stimulate", "Start positive pressure ventilation", "Intubate", "Start chest compressions"]', 0, 'The initial steps of resuscitation (Warm, dry, stimulate, clear airway) must always be performed first before assessing the need for PPV. (NRP)'),
    (v_topic_id, '125: An infant has a heart rate of 50 bpm despite 30 seconds of effective PPV and 60 seconds of coordinated chest compressions with 100% oxygen. What is the next step?",', '["Administer IV/IO Epinephrine", "Administer a fluid bolus", "Administer Sodium Bicarbonate", "Stop resuscitation efforts"]', 0, 'Epinephrine is indicated if the HR remains < 60 bpm despite adequate ventilation AND chest compressions. (NRP)'),
    (v_topic_id, '126: What is the preferred route for administering epinephrine during neonatal resuscitation if an umbilical venous catheter (UVC) cannot be immediately placed?",', '["Intraosseous (IO)", "Endotracheal tube (ET)", "Intramuscular (IM)", "Subcutaneous (SQ)"]', 0, 'IO access is rapid and highly effective in neonates when UVC access is delayed. ET administration requires a higher dose and is less reliable. (NRP)'),
    (v_topic_id, '127: A neonate requires emergent volume expansion for suspected hypovolemic shock (e.g., placental abruption). What fluid and dose is recommended by NRP?",', '["Normal Saline (0.9% NaCl) or O-negative blood at 10 mL/kg", "Lactated Ringer''s at 20 mL/kg", "5% Dextrose (D5W) at 10 mL/kg", "Albumin at 5 mL/kg"]', 0, 'The recommended volume expander is NS or uncrossmatched O-negative blood given as a 10 mL/kg bolus over 5-10 minutes. (NRP)'),
    (v_topic_id, '128: A neonate is delivered with the intestines protruding through a defect just to the right of the umbilicus. There is no covering membrane. What is the diagnosis?",', '["Gastroschisis", "Omphalocele", "Umbilical hernia", "Prune belly syndrome"]', 0, 'Gastroschisis. The bowel is exposed to amniotic fluid in utero, leading to inflammation and thickening. (First Aid)'),
    (v_topic_id, '129: What is a key initial management step in the delivery room for an infant born with gastroschisis?",', '["Place the lower half of the infant in a sterile bowel bag (silo) to prevent heat/fluid loss and protect the bowel", "Immediate primary surgical closure in the delivery room", "Apply a pressure dressing over the bowel", "Administer oral feeds to stimulate peristalsis"]', 0, 'Exposed bowel leads to massive insensible fluid and heat loss. Protecting the bowel with a silo and starting IV fluids and antibiotics is critical prior to surgical staging. (Case Files)'),
    (v_topic_id, '130: A 2-week-old premature infant is diagnosed with Necrotizing Enterocolitis (NEC). They are NPO on IV antibiotics. Suddenly, the infant''s abdomen becomes acutely distended and rigid, and the infant becomes hypotensive. What is the most likely complication and indicated treatment?",', '["Bowel perforation; requires exploratory laparotomy or peritoneal drain", "Intussusception; requires barium enema", "Sepsis; change antibiotics", "Hypoglycemia; administer IV dextrose"]', 0, 'Sudden clinical deterioration and a rigid abdomen in NEC indicates perforation (pneumoperitoneum). Immediate surgical intervention is required. (Nelson)'),
    (v_topic_id, '131: A term infant presents with delayed passage of meconium and abdominal distension. A rectal suction biopsy is performed. What histological finding confirms Hirschsprung disease?",', '["Absence of ganglion cells in the submucosal and myenteric plexuses", "Presence of meconium bodies", "Hypertrophy of the muscularis propria", "Eosinophilic infiltration"]', 0, 'The neural crest cells fail to migrate to the distal colon, leaving an aganglionic segment that remains tonically contracted. (Amboss)'),
    (v_topic_id, '132: What life-threatening complication can occur in infants with undiagnosed Hirschsprung disease?",', '["Hirschsprung-associated enterocolitis (HAEC)", "Gastric rupture", "Liver failure", "Chronic renal failure"]', 0, 'HAEC presents with fever, explosive foul-smelling diarrhea, and abdominal distension. It is a major cause of mortality and requires IV antibiotics and rectal irrigations. (UWorld)'),
    (v_topic_id, '133: A neonate presents with excessive drooling and cyanosis with feeding. An NGT is passed but coils in the upper chest. An X-ray shows the coiled NGT and air in the stomach. What specific type of tracheoesophageal anomaly is this?",', '["Proximal esophageal atresia with a distal tracheoesophageal fistula", "Pure esophageal atresia (no fistula)", "H-type tracheoesophageal fistula (no atresia)", "Proximal TEF with distal esophageal atresia"]', 0, 'This is the most common type (85%). The proximal esophagus ends in a blind pouch (causing drooling and coiled NGT). The distal esophagus connects the trachea to the stomach (allowing air into the stomach). (Case Files)'),
    (v_topic_id, '134: A neonate with esophageal atresia should be evaluated for other anomalies associated with the VACTERL association. What does VACTERL stand for?",', '["Vertebral, Anal atresia, Cardiac, TracheoEsophageal fistula, Renal, Limb anomalies", "Vascular, Airway, Cranial, Thoracic, Endocrine, Renal, Liver", "Visual, Auditory, Cardiac, Thyroid, Eye, Renal, Limb", "None of the above"]', 0, 'Infants with one VACTERL anomaly should be screened for the others (e.g., echo for cardiac, ultrasound for renal/spinal). (First Aid)'),
    (v_topic_id, '135: A neonate presents with respiratory distress. An X-ray shows cystic structures in the left lower lobe. CT scan confirms a multicystic mass of disorganized lung tissue that does not communicate with the tracheobronchial tree. Diagnosis?",', '["Congenital Pulmonary Airway Malformation (CPAM)", "Bronchopulmonary Sequestration", "Congenital Lobar Emphysema", "Diaphragmatic Hernia"]', 0, 'CPAM (formerly CCAM) is a hamartomatous lesion of the lung. It can cause respiratory distress by compressing normal lung tissue. (Nelson)'),
    (v_topic_id, '136: A neonate presents with respiratory distress. X-ray shows hyperinflation of the left upper lobe, compressing the surrounding structures and shifting the mediastinum to the right. Diagnosis?",', '["Congenital Lobar Emphysema (CLE)", "Pneumothorax", "Congenital Diaphragmatic Hernia", "CPAM"]', 0, 'CLE is characterized by overdistension of a single lobe (most commonly Left Upper Lobe) due to a ball-valve obstruction in the bronchus. (Amboss)'),
    (v_topic_id, '137: A neonate is diagnosed with developmental dysplasia of the hip (DDH) via a positive Ortolani maneuver. The infant is 2 weeks old. What is the standard first-line treatment?",', '["Pavlik harness", "Closed reduction and spica cast", "Open surgical reduction", "Observation only"]', 0, 'The Pavlik harness maintains the hips in flexion and abduction, keeping the femoral head reduced in the acetabulum to allow for proper remodeling. (Case Files)'),
    (v_topic_id, '138: Until what age is ultrasound preferred over X-ray for evaluating developmental dysplasia of the hip (DDH)?",', '["4-6 months", "1 month", "12 months", "2 years"]', 0, 'The femoral head and acetabulum are cartilaginous in the newborn. They do not ossify sufficiently to be reliably seen on X-ray until 4-6 months of age. (UWorld)'),
    (v_topic_id, '139: A 3-day-old infant presents with bilateral clubfoot (talipes equinovarus). The feet are plantarflexed, inverted, and adducted. What is the first-line treatment?",', '["Serial casting (Ponseti method) initiated shortly after birth", "Immediate surgical release of all tendons", "Special orthopedic shoes", "Observation until 1 year of age"]', 0, 'The Ponseti method involves weekly gentle manipulation and casting, followed usually by a percutaneous Achilles tenotomy, and is highly successful. (Nelson)'),
    (v_topic_id, '140: A newborn presents with a single, deep palmar crease, upslanting palpebral fissures, epicanthal folds, and hypotonia. What is the most common cause of this genetic syndrome?",', '["Meiotic nondisjunction of chromosome 21", "Robertsonian translocation", "Mosaicism", "Microdeletion"]', 0, 'Trisomy 21 (Down syndrome) is caused by meiotic nondisjunction in 95% of cases, heavily associated with advanced maternal age. (First Aid)'),
    (v_topic_id, '141: A neonate is born with microcephaly, rocker-bottom feet, clenched hands with overlapping fingers, and a prominent occiput. What is the diagnosis?",', '["Trisomy 18 (Edwards Syndrome)", "Trisomy 13 (Patau Syndrome)", "Trisomy 21 (Down Syndrome)", "Turner Syndrome"]', 0, 'Classic presentation of Trisomy 18. Prognosis is exceptionally poor, with most dying in the first year of life. (Case Files)'),
    (v_topic_id, '142: A neonate is born with microphthalmia, microcephaly, cleft lip/palate, polydactyly, and cutis aplasia (punched-out scalp lesions). What is the diagnosis?",', '["Trisomy 13 (Patau Syndrome)", "Trisomy 18 (Edwards Syndrome)", "Cri-du-chat syndrome", "DiGeorge syndrome"]', 0, 'Classic presentation of Trisomy 13. Midline defects (holoprosencephaly, clefts) and polydactyly are hallmarks. (Amboss)'),
    (v_topic_id, '143: A neonate presents with a high-pitched, cat-like cry, microcephaly, and a moon-like face. What is the genetic deletion?",', '["Microdeletion of the short arm of chromosome 5 (5p-)", "Microdeletion of 22q11", "Microdeletion of 15q11", "Microdeletion of 7q11"]', 0, 'Cri-du-chat (cry of the cat) syndrome. The abnormal cry is due to laryngeal hypoplasia. (UWorld)'),
    (v_topic_id, '144: A neonate presents with hypocalcemic tetany, a harsh systolic murmur (Truncus arteriosus), and absent thymic shadow on chest X-ray. What is the diagnosis and affected chromosome?",', '["DiGeorge Syndrome; 22q11.2 microdeletion", "Williams Syndrome; 7q11.23 microdeletion", "Prader-Willi Syndrome; 15q11 microdeletion", "Angelman Syndrome; 15q11 microdeletion"]', 0, 'DiGeorge syndrome (Catch-22: Cardiac anomalies, Abnormal facies, Thymic aplasia, Cleft palate, Hypocalcemia/Hypoparathyroidism). (Nelson)'),
    (v_topic_id, '145: A newborn male presents with marked hypotonia, poor feeding, and cryptorchidism. The parents are told the child will likely develop hyperphagia and obesity later in childhood. What is the diagnosis?",', '["Prader-Willi Syndrome", "Angelman Syndrome", "Fragile X Syndrome", "Kallmann Syndrome"]', 0, 'Prader-Willi is caused by the loss of the PATERNALLY contributed region of chromosome 15q11 (often via maternal uniparental disomy or paternal deletion). (First Aid)'),
    (v_topic_id, '146: A neonate is diagnosed with Cystic Fibrosis via newborn screen. What is the underlying pathophysiological defect?",', '["Defective CFTR protein leading to impaired chloride secretion and sodium absorption, resulting in thick, dehydrated secretions", "Deficiency of alpha-1 antitrypsin", "Defective ciliary dynein arms", "Absence of surfactant protein B"]', 0, 'The CFTR channel transports chloride out of cells. When defective, secretions become extremely thick, affecting the lungs, pancreas, and intestines (meconium ileus). (Case Files)'),
    (v_topic_id, '147: A term neonate develops profound hypoglycemia, hepatomegaly, and lactic acidosis when fasting. They have a "doll-like" face. Diagnosis?",', '["Von Gierke Disease (Glycogen Storage Disease Type I)", "Pompe Disease (GSD Type II)", "Cori Disease (GSD Type III)", "McArdle Disease (GSD Type V)"]', 0, 'Deficiency of glucose-6-phosphatase prevents the liver from releasing glucose into the blood during fasting. Requires frequent carbohydrate feeds (cornstarch). (Amboss)'),
    (v_topic_id, '148: A neonate presents with severe hypotonia, cardiomegaly, and heart failure within the first few weeks of life. Diagnosis?",', '["Pompe Disease (Glycogen Storage Disease Type II)", "Von Gierke Disease", "Tay-Sachs Disease", "Niemann-Pick Disease"]', 0, 'Deficiency of lysosomal acid alpha-glucosidase. Glycogen accumulates in the lysosomes of the heart and skeletal muscle. "Pompe trashes the Pump." (UWorld)'),
    (v_topic_id, '149: A neonate of Ashkenazi Jewish descent appears normal at birth but begins to lose motor milestones at 3-6 months. Exam reveals an exaggerated startle reflex and a "cherry-red spot" on the macula. There is NO hepatosplenomegaly. Diagnosis?",', '["Tay-Sachs Disease", "Niemann-Pick Disease", "Gaucher Disease", "Krabbe Disease"]', 0, 'Tay-Sachs is a deficiency of hexosaminidase A, leading to GM2 ganglioside accumulation. Niemann-Pick ALSO has a cherry-red spot but HAS hepatosplenomegaly. (First Aid)'),
    (v_topic_id, '150: A neonate presents with a cherry-red spot on the macula and massive hepatosplenomegaly. Diagnosis?",', '["Niemann-Pick Disease", "Tay-Sachs Disease", "Metachromatic Leukodystrophy", "Hurler Syndrome"]', 0, 'Niemann-Pick is a deficiency of sphingomyelinase. The hepatosplenomegaly distinguishes it from Tay-Sachs. (Nelson)'),
    (v_topic_id, '151: A neonate presents with coarse facial features, corneal clouding, hepatosplenomegaly, and restricted joint mobility. Diagnosis?",', '["Hurler Syndrome (Mucopolysaccharidosis Type I)", "Hunter Syndrome (MPS Type II)", "Tay-Sachs Disease", "Gaucher Disease"]', 0, 'Deficiency of alpha-L-iduronidase leads to heparan and dermatan sulfate accumulation. Hunter syndrome is similar but X-linked and lacks corneal clouding ("Hunters see clearly"). (Case Files)'),
    (v_topic_id, '152: What is the most common cause of congenital hypothyroidism in the United States?",', '["Thyroid dysgenesis (aplasia, hypoplasia, or ectopic gland)", "Iodine deficiency", "Dyshormonogenesis", "Maternal anti-thyroid antibodies"]', 0, 'Most cases are due to dysgenesis. Universal newborn screening is critical because infants are often asymptomatic at birth (due to maternal thyroid hormone) but will develop severe intellectual disability (cretinism) if untreated. (Amboss)'),
    (v_topic_id, '153: A 4-week-old infant who missed their newborn screen presents with lethargy, poor feeding, a hoarse cry, prolonged jaundice, an umbilical hernia, and macroglossia. Diagnosis?",', '["Congenital Hypothyroidism", "Down Syndrome", "Congenital Adrenal Hyperplasia", "Sepsis"]', 0, 'Classic signs of congenital hypothyroidism (cretinism) that develop after maternal thyroid hormone wanes. Requires immediate Levothyroxine. (UWorld)'),
    (v_topic_id, '154: A newborn male presents with poor feeding, vomiting, and a distinctly "mousy" or "musty" body odor. Diagnosis?",', '["Phenylketonuria (PKU)", "Maple Syrup Urine Disease", "Isovaleric acidemia", "Tyrosinemia"]', 0, 'The musty odor is a hallmark of PKU, caused by phenylacetate accumulation. (First Aid)'),
    (v_topic_id, '155: A newborn presents with poor feeding, lethargy, and urine that smells like burnt sugar. Diagnosis?",', '["Maple Syrup Urine Disease (MSUD)", "Phenylketonuria", "Alkaptonuria", "Homocystinuria"]', 0, 'MSUD is caused by a defect in branched-chain alpha-keto acid dehydrogenase, leading to the accumulation of Leucine, Isoleucine, and Valine. (Nelson)'),
    (v_topic_id, '156: A term neonate is born via precipitate delivery. The infant is completely apneic, cyanotic, and limp. Heart rate is 80 bpm. What is the APGAR score at 1 minute if there is no response to stimulation?",', '["1", "2", "3", "0"]', 0, 'Appearance: 0 (blue). Pulse: 1 (<100). Grimace: 0 (none). Activity: 0 (limp). Respiration: 0 (absent). Total = 1. (Case Files)'),
    (v_topic_id, '157: A neonate develops polycythemia (Hct 72%). Which of the following is a known risk factor for neonatal polycythemia?",', '["Maternal diabetes mellitus", "Prematurity", "Maternal anemia", "Neonatal sepsis"]', 0, 'Maternal diabetes causes fetal hyperglycemia and hyperinsulinemia, leading to increased fetal metabolic rate and chronic hypoxia. This stimulates erythropoietin production, causing polycythemia. (Amboss)'),
    (v_topic_id, '158: A premature infant is born at 24 weeks gestation. What prophylactic medication should be administered into the endotracheal tube shortly after birth to prevent respiratory distress syndrome?",', '["Exogenous pulmonary surfactant", "Epinephrine", "Budesonide", "Albuterol"]', 0, 'Surfactant administration dramatically reduces the severity of RDS and mortality in extremely premature infants. (UWorld)'),
    (v_topic_id, '159: An infant is born to a mother with a history of Graves disease treated with propylthiouracil. The neonate presents with tachycardia, irritability, poor weight gain, and exophthalmos. Diagnosis?",', '["Neonatal thyrotoxicosis", "Congenital hypothyroidism", "Neonatal abstinence syndrome", "Sepsis"]', 0, 'Neonatal thyrotoxicosis is caused by transplacental passage of maternal Thyroid Stimulating Immunoglobulins (TSI). It is transient but can be life-threatening and may require treatment with methimazole and beta-blockers. (Nelson)'),
    (v_topic_id, '160: A neonate presents with a large, fluid-filled mass on the posterior/lateral neck that transilluminates. It is associated with Turner syndrome. Diagnosis?",', '["Cystic hygroma", "Thyroglossal duct cyst", "Branchial cleft cyst", "Cervical teratoma"]', 0, 'A cystic hygroma is a macroscopic lymphatic malformation. It is highly associated with Turner syndrome (45,X) and Down syndrome. (First Aid)'),
    (v_topic_id, '161: A newborn presents with a midline neck mass that moves upwards when the infant swallows or protrudes the tongue. Diagnosis?",', '["Thyroglossal duct cyst", "Branchial cleft cyst", "Cystic hygroma", "Dermoid cyst"]', 0, 'Thyroglossal duct cysts are remnants of the descending thyroid gland. They are midline and move with swallowing. (Case Files)'),
    (v_topic_id, '162: A newborn presents with a lateral neck mass anterior to the sternocleidomastoid muscle. A small sinus tract is noted. Diagnosis?",', '["Branchial cleft cyst", "Thyroglossal duct cyst", "Cystic hygroma", "Lymphadenitis"]', 0, 'Branchial cleft cysts arise from failure of obliteration of the branchial clefts. They are located laterally. (Amboss)'),
    (v_topic_id, '163: A neonate develops bleeding from the umbilical stump and a cephalhematoma on day 3 of life. PT and PTT are significantly prolonged. The infant was born at home and received no standard newborn prophylactic care. What is the diagnosis?",', '["Hemorrhagic Disease of the Newborn (Vitamin K Deficiency Bleeding)", "Hemophilia A", "von Willebrand Disease", "Disseminated Intravascular Coagulation (DIC)"]', 0, 'Classic presentation of late Vitamin K deficiency bleeding due to failure to administer IM Vitamin K at birth. Vitamin K is required for factors II, VII, IX, X, C, and S. (UWorld)'),
    (v_topic_id, '164: Why are newborns naturally deficient in Vitamin K?",', '["Poor placental transfer, sterile gut (no bacteria to produce it), and low levels in breast milk", "Rapid consumption by the neonatal liver", "Maternal antibodies destroy fetal Vitamin K", "Neonates excrete Vitamin K rapidly in urine"]', 0, 'The combination of these three factors makes newborns highly susceptible to bleeding until their gut flora establishes. (Nelson)'),
    (v_topic_id, '165: A term neonate has not passed meconium at 36 hours. Exam shows a normal anus. The abdomen is distended. Which condition is the most likely cause?",', '["Hirschsprung disease", "Imperforate anus", "Duodenal atresia", "Pyloric stenosis"]', 0, 'Failure to pass meconium > 24-48 hours in a term infant is the hallmark of Hirschsprung disease. Imperforate anus would be noted on exam. (First Aid)'),
    (v_topic_id, '166: A newborn is noted to have a scaphoid abdomen, severe respiratory distress, and heart sounds loudest on the right side of the chest. Where is the defect located?",', '["Left posterolateral diaphragm (Bochdalek hernia)", "Right anteromedial diaphragm (Morgagni hernia)", "Central tendon of the diaphragm", "Esophageal hiatus"]', 0, 'The classic left-sided Bochdalek hernia allows bowel to enter the left chest, pushing the heart to the right and causing a scaphoid (sunken) abdomen. (Case Files)'),
    (v_topic_id, '167: A neonate with Congenital Diaphragmatic Hernia requires surgical repair. When is the optimal time for surgery?",', '["After the infant is stabilized and pulmonary hypertension is medically managed (usually days to weeks later)", "Immediately in the delivery room", "Within the first 2 hours of life", "At 6 months of age"]', 0, 'CDH is a PHYSIOLOGIC emergency (pulmonary hypoplasia/hypertension), NOT a surgical emergency. The infant must be stabilized on a ventilator (or ECMO) before undergoing surgery. (Amboss)'),
    (v_topic_id, '168: A neonate is born to an Rh-negative mother. The neonate is Rh-positive. The mother received inadequate RhoGAM during pregnancy. The neonate presents with severe hydrops fetalis (generalized edema, pleural effusions, ascites). What is the underlying pathophysiology?",', '["Severe anemia leading to high-output heart failure", "Severe liver failure", "Renal agenesis", "Congenital heart defect"]', 0, 'Maternal IgG antibodies destroy fetal RBCs. The severe anemia causes extramedullary hematopoiesis and profound high-output heart failure, leading to massive edema (hydrops fetalis). (UWorld)'),
    (v_topic_id, '169: What is the purpose of administering Rho(D) immune globulin (RhoGAM) to an Rh-negative mother?",', '["To prevent the mother from developing anti-D IgG antibodies by neutralizing fetal Rh-positive RBCs in the maternal circulation", "To treat the fetus''s anemia", "To prevent ABO incompatibility", "To suppress the maternal cellular immune response"]', 0, 'RhoGAM binds to fetal Rh-positive RBCs in the maternal bloodstream, preventing the mother''s immune system from recognizing them and creating memory B cells. (Nelson)'),
    (v_topic_id, '170: A neonate is diagnosed with ABO incompatibility. The mother is type O, and the infant is type A. Why is ABO incompatibility generally milder than Rh incompatibility?",', '["Anti-A/B antibodies are primarily IgM and do not cross the placenta, while the IgG antibodies that do cross are in smaller amounts", "A/B antigens are not expressed on fetal red blood cells", "The fetal liver rapidly metabolizes anti-A/B antibodies", "ABO incompatibility only occurs in the second pregnancy"]', 0, 'Most anti-A/B antibodies are IgM. The subset that is IgG crosses the placenta but causes milder hemolysis compared to the potent IgG response in Rh sensitization. It can occur in the FIRST pregnancy. (First Aid)'),
    (v_topic_id, '171: A neonate presents with jitteriness and a prolonged QT interval on ECG. Labs show a total calcium of 6.5 mg/dL (low). What is the treatment for symptomatic neonatal hypocalcemia?",', '["Intravenous Calcium Gluconate", "Oral Calcium Carbonate", "Vitamin D supplementation", "Magnesium Sulfate"]', 0, 'Symptomatic hypocalcemia (tetany, seizures, prolonged QT) requires immediate IV Calcium Gluconate. (Case Files)'),
    (v_topic_id, '172: DiGeorge syndrome involves failure of development of the 3rd and 4th pharyngeal pouches. This leads to absence of the thymus and what other endocrine gland?",', '["Parathyroid glands (causing hypocalcemia)", "Thyroid gland", "Adrenal glands", "Pituitary gland"]', 0, 'Aplasia of the parathyroid glands causes profound hypocalcemia in the neonatal period. (Amboss)'),
    (v_topic_id, '173: A 3-week-old infant presents with vomiting, poor feeding, and lethargy. The mother mixed the formula with excessive amounts of water to save money. The infant is seizing. What is the likely electrolyte abnormality?",', '["Severe Hyponatremia (water intoxication)", "Hypernatremia", "Hyperkalemia", "Hypocalcemia"]', 0, 'Diluted formula provides excessive free water, leading to dilutional hyponatremia, cerebral edema, and seizures. (UWorld)'),
    (v_topic_id, '174: A neonate is born at 42 weeks gestation. The skin is peeling, there is loss of subcutaneous fat, and the fingernails are long and stained with meconium. What is this clinical picture called?",', '["Post-maturity syndrome (Dysmaturity)", "Prematurity", "Intrauterine Growth Restriction (IUGR)", "SGA (Small for Gestational Age)"]', 0, 'Post-maturity syndrome occurs due to placental insufficiency after 40-41 weeks. The fetus consumes its own fat/glycogen stores to survive. (Nelson)'),
    (v_topic_id, '175: A neonate has a birth weight below the 10th percentile. Head circumference is normal, but weight and length are restricted (asymmetric IUGR). What is the most common cause?",', '["Late-onset placental insufficiency (e.g., maternal hypertension, preeclampsia)", "Chromosomal abnormalities (e.g., Trisomy 18)", "Congenital TORCH infections", "Maternal drug use in the first trimester"]', 0, 'Asymmetric IUGR (head-sparing) usually results from a problem late in pregnancy (placental insufficiency). The fetus shunts blood to the brain, preserving head growth at the expense of body fat/muscle. (First Aid)'),
    (v_topic_id, '176: A neonate has a birth weight, length, and head circumference all below the 10th percentile (symmetric IUGR). What is the most common etiology?",', '["Early insult such as chromosomal abnormalities or congenital TORCH infections", "Maternal preeclampsia in the third trimester", "Gestational diabetes", "Multiple gestation"]', 0, 'Symmetric IUGR implies an early, intrinsic problem with cellular growth affecting the entire body uniformly. (Case Files)'),
    (v_topic_id, '177: A neonate presents with a single umbilical artery. What organ system should be evaluated for associated anomalies?",', '["Renal/Genitourinary tract", "Central Nervous System", "Respiratory tract", "Gastrointestinal tract"]', 0, 'A single umbilical artery (normally 2 arteries, 1 vein) is associated with renal anomalies. A renal ultrasound is often recommended. (Amboss)'),
    (v_topic_id, '178: An infant is born with a cleft lip and palate. The mother asks when the surgeries will typically occur. What is the standard timeline?",', '["Cleft lip at 3 months, cleft palate at 9-12 months", "Both immediately after birth", "Cleft palate at 3 months, cleft lip at 2 years", "Both at 2 years of age"]', 0, 'The "Rule of 10s" for cleft lip repair: 10 weeks old, 10 pounds, 10g hemoglobin. Palate repair is delayed to 9-12 months to allow for jaw growth but completed before significant speech development. (UWorld)'),
    (v_topic_id, '179: A neonate has a large port-wine stain over the right face and new-onset focal seizures of the left arm. What imaging finding is classic for this syndrome?",', '["Tram-track calcifications in the cerebral cortex on CT/MRI", "Periventricular calcifications", "Diffuse intracranial calcifications", "Hydrocephalus"]', 0, 'Sturge-Weber syndrome is characterized by leptomeningeal angiomas that lead to classic "tram-track" cortical calcifications. (Nelson)'),
    (v_topic_id, '180: A neonate presents with hypopigmented macules (ash-leaf spots). What cardiac tumor is heavily associated with this syndrome?",', '["Rhabdomyoma", "Myxoma", "Fibroma", "Teratoma"]', 0, 'Tuberous Sclerosis is associated with cardiac rhabdomyomas, which are benign and often spontaneously regress. (First Aid)'),
    (v_topic_id, '181: A newborn is noted to have a white pupillary reflex (leukocoria). What is the most critical diagnosis to rule out?",', '["Retinoblastoma", "Cataracts", "Glaucoma", "Retinal detachment"]', 0, 'Leukocoria is the classic presentation of retinoblastoma, a malignant tumor of the retina. It requires immediate ophthalmologic evaluation to save the eye and the child''s life. (Case Files)'),
    (v_topic_id, '182: A neonate presents with hypotonia, a weak cry, and profound generalized weakness (floppy baby). The mother notes decreased fetal movements during pregnancy. Deep tendon reflexes are absent. Fasciculations of the tongue are noted. Diagnosis?",', '["Spinal Muscular Atrophy (SMA) Type 1 (Werdnig-Hoffmann disease)", "Cerebral Palsy", "Botulism", "Myasthenia Gravis"]', 0, 'SMA Type 1 is a severe autosomal recessive disease causing destruction of anterior horn cells (lower motor neuron lesion). (Amboss)'),
    (v_topic_id, '183: A 4-week-old infant presents with acute onset of generalized weakness, loss of head control, a weak cry, and constipation. The parents recently fed the infant honey. Diagnosis?",', '["Infant Botulism", "Spinal Muscular Atrophy", "Guillain-Barre Syndrome", "Sepsis"]', 0, 'Infant botulism occurs via ingestion of Clostridium botulinum spores (in honey or dust), which germinate in the gut and produce a toxin that blocks presynaptic acetylcholine release. (UWorld)'),
    (v_topic_id, '184: What is the specific treatment for Infant Botulism?",', '["Human Botulism Immune Globulin (BabyBIG)", "Intravenous Antibiotics (e.g., Penicillin)", "Equine botulinum antitoxin", "Edrophonium"]', 0, 'Antibiotics are CONTRAINDICATED as they lyse the bacteria, releasing more toxin. BabyBIG neutralizes the circulating toxin. (Nelson)'),
    (v_topic_id, '185: A neonate is born with a heart rate of 120, strong cry, active motion, sneezing when stimulated, and pink body with blue hands/feet. APGAR score?",', '["9", "10", "8", "7"]', 0, 'HR>100 (2), Cry (2), Active (2), Sneeze/Grimace (2), Acrocyanosis (1). Total = 9. (First Aid)'),
    (v_topic_id, '186: A neonate presents with vomiting, bloody diarrhea, and eczema. The mother is exclusively breastfeeding but eats a varied diet. The infant is diagnosed with Food Protein-Induced Allergic Proctocolitis. What is the most likely offending agent and management?",', '["Cow''s milk protein; Mother must strictly eliminate all dairy from her diet", "Lactose; Switch to soy formula", "Gluten; Mother must avoid wheat", "Fructose; Avoid fruit juices"]', 0, 'Cow''s milk protein allergy is a non-IgE mediated allergy. The proteins pass into breast milk. If breastfeeding, the mother must eliminate dairy (and often soy). If formula-feeding, switch to an extensively hydrolyzed formula. (Case Files)'),
    (v_topic_id, '187: A neonate presents with stridor that worsens when supine and improves when prone. The stridor is inspiratory and high-pitched. Laryngoscopy shows collapse of omega-shaped epiglottis during inspiration. Diagnosis?",', '["Laryngomalacia", "Tracheomalacia", "Vascular ring", "Vocal cord paralysis"]', 0, 'Laryngomalacia is the most common cause of stridor in infants. It is usually benign and resolves spontaneously by 12-18 months of age as the cartilage stiffens. (Amboss)'),
    (v_topic_id, '188: A neonate presents with biphasic stridor (inspiratory and expiratory) and dysphagia. A barium swallow shows posterior compression of the esophagus. Diagnosis?",', '["Vascular ring (e.g., double aortic arch)", "Laryngomalacia", "Tracheomalacia", "Foreign body"]', 0, 'A vascular ring encircles both the trachea (causing stridor) and the esophagus (causing dysphagia/solid food aversion). (UWorld)'),
    (v_topic_id, '189: A premature neonate (28 weeks) requires prolonged mechanical ventilation. At 36 weeks post-menstrual age, the infant still requires supplemental oxygen and has diffuse fibrotic changes on CXR. Diagnosis?",', '["Bronchopulmonary Dysplasia (BPD)", "Respiratory Distress Syndrome", "Transient Tachypnea of the Newborn", "Neonatal Pneumonia"]', 0, 'BPD (Chronic Lung Disease of Prematurity) is defined as an oxygen requirement > 28 days or at 36 weeks PMA, caused by barotrauma, oxygen toxicity, and inflammation. (Nelson)'),
    (v_topic_id, '190: A neonate presents with a webbed neck, low posterior hairline, shield chest with widely spaced nipples, and edema of the hands and feet. Karyotype shows 45,XO. What is the mechanism of the hand/foot edema?",', '["Congenital lymphedema due to abnormal lymphatic network development", "Heart failure", "Renal failure", "Hypoalbuminemia"]', 0, 'The lymphedema in Turner syndrome is a classic physical finding at birth, often leading to cystic hygromas in utero. (First Aid)'),
    (v_topic_id, '191: A newborn male presents with a very large, distended abdomen with wrinkled, thin skin ("prune-like"). He has bilateral cryptorchidism. Ultrasound shows massively dilated ureters and a distended bladder. Diagnosis?",', '["Prune Belly Syndrome (Eagle-Barrett Syndrome)", "Posterior Urethral Valves", "Polycystic Kidney Disease", "Omphalocele"]', 0, 'Triad: Absent abdominal musculature, severe urinary tract anomalies, and cryptorchidism. (Case Files)'),
    (v_topic_id, '192: A newborn male presents with a poor, dribbling urinary stream and a distended bladder. Prenatal ultrasound showed bilateral hydronephrosis and oligohydramnios. What is the most likely diagnosis?",', '["Posterior Urethral Valves (PUV)", "Ureteropelvic junction obstruction", "Prune Belly Syndrome", "Hypospadias"]', 0, 'PUV is the most common cause of severe obstructive uropathy in male infants. A flap of tissue obstructs the urethra, leading to bladder hypertrophy and hydronephrosis. (Amboss)'),
    (v_topic_id, '193: What is the definitive diagnostic test for Posterior Urethral Valves?",', '["Voiding Cystourethrogram (VCUG)", "Renal Ultrasound", "Intravenous Pyelogram (IVP)", "CT scan of the abdomen"]', 0, 'VCUG will show a dilated posterior urethra and a dilated, hypertrophied bladder, confirming the obstruction during voiding. (UWorld)'),
    (v_topic_id, '194: A newborn has oligohydramnios in utero. At birth, the infant has a flattened face, low-set ears, a beak-like nose, and clubfeet. Shortly after birth, the infant develops severe respiratory distress and dies. What is this sequence of events called and what is the underlying primary defect?",', '["Potter Sequence; Bilateral renal agenesis", "Pierre Robin Sequence; Micrognathia", "Oligohydramnios sequence; Amniotic band syndrome", "VACTERL association; Renal anomaly"]', 0, 'Bilateral renal agenesis -> no fetal urine -> severe oligohydramnios. The lack of fluid causes fetal compression (Potter facies, clubfeet) and prevents normal lung development (pulmonary hypoplasia), which is the cause of death. (Nelson)'),
    (v_topic_id, '195: A newborn female has ambiguous genitalia (virilized) and is hypotensive and hyponatremic. What enzyme is deficient?",', '["21-hydroxylase", "11-beta-hydroxylase", "17-alpha-hydroxylase", "5-alpha-reductase"]', 0, 'Classic 21-hydroxylase deficiency CAH. 11-beta would present with hypertension. (First Aid)'),
    (v_topic_id, '196: A newborn male appears phenotypically female at birth but develops severe virilization and ambiguous genitalia during puberty. What is the enzyme deficiency?",', '["5-alpha-reductase deficiency", "Complete Androgen Insensitivity Syndrome", "21-hydroxylase deficiency", "Aromatase deficiency"]', 0, '5-alpha-reductase converts testosterone to DHT. Without DHT, male external genitalia do not develop in utero. At puberty, the massive surge in testosterone causes virilization. (Case Files)'),
    (v_topic_id, '197: A phenotypically normal female infant is evaluated for an inguinal hernia. During surgery, a testis is found in the hernia sac. Karyotype is 46,XY. Diagnosis?",', '["Complete Androgen Insensitivity Syndrome (CAIS)", "5-alpha-reductase deficiency", "Turner syndrome", "Klinefelter syndrome"]', 0, 'CAIS is due to a mutated androgen receptor. The patient produces testosterone and AMH (Mullerian structures regress, so no uterus), but cannot respond to testosterone, developing female external genitalia. (Amboss)'),
    (v_topic_id, '198: A neonate presents with jitteriness. Glucose is normal. Calcium is normal. The mother has a history of poorly controlled diabetes. Serum magnesium is 1.0 mg/dL. What is the cause of the hypomagnesemia?",', '["Maternal hypomagnesemia secondary to increased renal losses from diabetes", "Congenital defect in magnesium absorption", "Hypoparathyroidism", "Diuretic use"]', 0, 'Maternal diabetes causes increased urinary excretion of magnesium. The fetus becomes magnesium deficient, which can also impair PTH release, causing concurrent hypocalcemia. (UWorld)'),
    (v_topic_id, '199: A neonate develops an umbilical hernia. It is reducible and 2 cm in diameter. What is the appropriate management?",', '["Reassure and observe; most close spontaneously by age 4-5", "Immediate surgical repair", "Apply a pressure dressing or coin over the hernia", "Repair at 1 year of age"]', 0, 'Umbilical hernias are very common, especially in African American infants, and almost always close spontaneously without intervention. Strapping a coin over it is contraindicated. (Nelson)'),
    (v_topic_id, '200: A neonate presents with an indirect inguinal hernia. What is the appropriate management?",', '["Elective surgical repair (herniorrhaphy) in the near future (e.g., before 1-2 months) to prevent incarceration", "Observe until age 5 for spontaneous closure", "Apply a truss", "Immediate emergency surgery"]', 0, 'Unlike umbilical hernias, inguinal hernias DO NOT close spontaneously and carry a high risk of incarceration/strangulation in infants. Elective repair should be scheduled soon. (Case Files)'),
    (v_topic_id, '201: A 2-day-old infant is found to have a clavicle fracture from a difficult delivery. What is the classic physical exam finding to elicit this?",', '["Positive Ortolani maneuver", "Asymmetric Moro reflex", "Absent grasp reflex", "Positive Babinski reflex"]', 1, 'The infant will not abduct the arm on the affected side during the Moro reflex due to pain. (Nelson)'),
    (v_topic_id, '202: A term neonate is born to a mother with systemic lupus erythematosus (SLE). The infant presents with a maculopapular rash and a heart rate of 55 bpm. What is the diagnosis?",', '["Neonatal Lupus with Congenital Heart Block", "Congenital Rubella", "Neonatal Sepsis", "Normal sinus arrhythmia"]', 0, 'Maternal anti-SSA (Ro) and anti-SSB (La) antibodies cross the placenta and destroy the fetal AV node, causing irreversible complete (3rd degree) heart block. (First Aid)'),
    (v_topic_id, '203: A neonate is diagnosed with complete congenital heart block due to Neonatal Lupus. What is the definitive treatment?",', '["Permanent pacemaker placement", "Corticosteroids", "IVIG", "Atropine"]', 0, 'The destruction of the AV node is irreversible. Most symptomatic infants require a permanent pacemaker. (Amboss)'),
    (v_topic_id, '204: A premature neonate develops osteopenia of prematurity. Which of the following is the most important prophylactic measure?",', '["Provide breast milk fortifier containing calcium and phosphorus", "Administer high-dose IV calcium gluconate daily", "Limit physical handling", "Administer bisphosphonates"]', 0, 'Premature infants miss out on the massive calcium/phosphorus accretion that occurs in the 3rd trimester. Breast milk alone does not contain enough Ca/P for a premature infant''s bone growth, necessitating fortifiers. (UWorld)'),
    (v_topic_id, '205: A neonate presents with a midline abdominal wall defect covered by a membrane, containing both bowel and liver. The mother had polyhydramnios. What chromosomal anomaly is MOST strongly associated with this specific finding?",', '["Trisomy 21", "Trisomy 18 (Edwards Syndrome)", "Trisomy 13 (Patau Syndrome)", "Turner Syndrome"]', 1, 'Omphalocele is highly associated with Trisomy 18 and Trisomy 13. While it can occur in Trisomy 21, it is much more characteristic of 18 and 13. (Case Files)'),
    (v_topic_id, '206: A neonate with Beckwith-Wiedemann Syndrome has an omphalocele and macroglossia. What routine screening must be performed throughout childhood for this patient?",', '["Echocardiograms every 6 months", "Abdominal ultrasounds every 3 months", "Cranial ultrasounds monthly", "Hearing screens every 6 months"]', 1, 'BWS patients have a significantly increased risk of embryonal tumors, specifically Wilms tumor and hepatoblastoma. Routine abdominal ultrasounds and AFP levels are required until age 8. (Nelson)'),
    (v_topic_id, '207: A 2-day-old infant passes a stool that contains a small amount of bright red blood. The infant is exclusively breastfed, appears well, and the abdomen is soft. The mother reports sore, cracked nipples. What is the most likely cause?",', '["Necrotizing enterocolitis", "Swallowed maternal blood syndrome", "Milk protein allergy", "Anal fissure"]', 1, 'Swallowed maternal blood from cracked nipples is a common, benign cause of blood in the neonatal stool or vomitus. (Amboss)'),
    (v_topic_id, '208: What simple bedside test can differentiate swallowed maternal blood from neonatal gastrointestinal bleeding?",', '["Apt-Downey test", "Guaiac test (Hemoccult)", "pH testing", "Wright stain"]', 0, 'The Apt-Downey test uses alkali (NaOH) to differentiate fetal hemoglobin (resists denaturation, stays pink) from adult maternal hemoglobin (denatures, turns yellow/brown). (First Aid)'),
    (v_topic_id, '209: A newborn presents with a single, large, central incisor. This finding is highly associated with what severe midline brain defect?",', '["Holoprosencephaly", "Hydrocephalus", "Anencephaly", "Encephalocele"]', 0, 'A single central incisor is a microform of holoprosencephaly (failure of the forebrain to divide), which is a classic feature of Trisomy 13. (Case Files)'),
    (v_topic_id, '210: A neonate is diagnosed with anencephaly on prenatal ultrasound. What maternal supplement prior to conception could have significantly reduced the risk of this defect?",', '["Iron", "Folic Acid (Vitamin B9)", "Calcium", "Vitamin D"]', 1, 'Folic acid supplementation (400 mcg daily) before and during early pregnancy drastically reduces the risk of neural tube defects (anencephaly, spina bifida). (Nelson)'),
    (v_topic_id, '211: A neonate presents with a tuft of hair over the lower spine. An ultrasound reveals a tethered spinal cord. What long-term complication is the infant at risk for if left untreated?",', '["Hydrocephalus", "Progressive lower extremity weakness, spasticity, and bladder/bowel incontinence", "Scoliosis", "Meningitis"]', 1, 'As the child grows, the tethered cord is stretched, causing progressive neurological damage to the lower extremities and sphincters. Requires surgical release. (UWorld)'),
    (v_topic_id, '212: A premature infant (30 weeks) is noted to have a large patent ductus arteriosus (PDA) causing heart failure. Medical management with Indomethacin has failed. What is the next step?",', '["Observation", "Surgical ligation of the PDA", "Administer Prostaglandin E1", "Balloon atrial septostomy"]', 1, 'If symptomatic and medical management (COX inhibitors) fails or is contraindicated, surgical ligation or catheter-based closure is required. (Amboss)'),
    (v_topic_id, '213: A term neonate presents with cyanosis that worsens with crying. A harsh systolic ejection murmur is heard at the left upper sternal border. The ECG shows right ventricular hypertrophy. What is the most likely diagnosis?",', '["Transposition of the Great Arteries", "Tetralogy of Fallot", "Truncus Arteriosus", "Tricuspid Atresia"]', 1, 'Cyanosis that WORSENS with crying (increasing right-to-left shunt via RV outflow tract spasm) is the classic "Tet spell" seen in Tetralogy of Fallot. (First Aid)'),
    (v_topic_id, '214: During a "Tet spell" in an infant with Tetralogy of Fallot, what is the physiological purpose of placing the infant in a knee-to-chest position?",', '["It increases pulmonary vascular resistance", "It increases systemic vascular resistance, reducing the right-to-left shunt", "It decreases venous return to the heart", "It opens the ductus arteriosus"]', 1, 'Knee-to-chest position compresses the femoral arteries, sharply increasing SVR. This forces blood from the RV to go through the pulmonary artery rather than across the VSD into the aorta. (Nelson)'),
    (v_topic_id, '215: A newborn has bounding peripheral pulses and a wide pulse pressure. Which congenital heart defect is most likely?",', '["Patent Ductus Arteriosus (PDA)", "Coarctation of the Aorta", "Ventricular Septal Defect", "Tetralogy of Fallot"]', 0, 'The continuous run-off of blood from the aorta into the pulmonary artery during diastole lowers the diastolic pressure, creating a wide pulse pressure and bounding pulses. (Case Files)'),
    (v_topic_id, '216: A 1-week-old infant presents in shock with pale, cold legs and absent femoral pulses, but the right arm is pink with strong pulses. What is the diagnosis?",', '["Critical Coarctation of the Aorta", "Patent Ductus Arteriosus", "Tetralogy of Fallot", "Aortic Stenosis"]', 0, 'The coarctation is typically located just distal to the left subclavian artery. When the PDA closes, blood flow to the descending aorta is severely restricted. (UWorld)'),
    (v_topic_id, '217: A neonate presents with an isolated cleft lip. The parents are healthy. What is the most likely etiology?",', '["Single gene mutation", "Chromosomal aneuploidy", "Multifactorial inheritance", "Teratogen exposure"]', 2, 'Cleft lip/palate is the classic example of multifactorial inheritance (a combination of multiple genes and environmental factors). (Amboss)'),
    (v_topic_id, '218: A term neonate is born with a very small mandible, a cleft palate, and respiratory distress. Which of the following is the most likely underlying genetic syndrome, knowing it is often associated with this sequence?",', '["Trisomy 21", "Stickler syndrome", "Turner syndrome", "Klinefelter syndrome"]', 1, 'While Pierre Robin sequence can be isolated, it is frequently part of a larger syndrome, most commonly Stickler syndrome (a collagen connective tissue disorder affecting eyes, ears, and joints). (First Aid)'),
    (v_topic_id, '219: A neonate presents with craniosynostosis (premature fusion of cranial sutures), midface hypoplasia, and broad thumbs and broad great toes. Diagnosis?",', '["Crouzon syndrome", "Apert syndrome", "Pfeiffer syndrome", "Saethre-Chotzen syndrome"]', 2, 'Broad thumbs and toes are the hallmark differentiating feature of Pfeiffer syndrome from other craniosynostosis syndromes like Crouzon or Apert. (Nelson)'),
    (v_topic_id, '220: A neonate is born with syndactyly (fusion) of the digits of the hands and feet ("mitten hands") and severe craniosynostosis. Diagnosis?",', '["Apert syndrome", "Crouzon syndrome", "Pfeiffer syndrome", "Pierre Robin sequence"]', 0, 'Apert syndrome is characterized by severe craniosynostosis and complex syndactyly of the hands and feet. (Case Files)'),
    (v_topic_id, '221: A 1-day-old infant has a large, beefy red, sharply demarcated plaque over the perineum and buttocks. Satellite lesions are present. Diagnosis and treatment?",', '["Diaper dermatitis (irritant); Zinc oxide", "Candidal diaper dermatitis; Topical Nystatin or Clotrimazole", "Seborrheic dermatitis; Hydrocortisone", "Impetigo; Mupirocin"]', 1, 'The presence of satellite lesions (small papules/pustules outside the main plaque) and involvement of the skin folds (creases) strongly point to Candida albicans. (UWorld)'),
    (v_topic_id, '222: A 2-week-old infant has a greasy, yellow, scaly rash on the scalp ("cradle cap") and in the diaper folds. The infant is not bothered by the rash. Diagnosis?",', '["Candidal dermatitis", "Atopic dermatitis (Eczema)", "Seborrheic dermatitis", "Psoriasis"]', 2, 'Seborrheic dermatitis is common, benign, and typically asymptomatic. It involves sebum-rich areas (scalp, face, folds). Treated with mild baby shampoo or gentle emollients. (Amboss)'),
    (v_topic_id, '223: A neonate presents with intensely pruritic, erythematous patches with weeping and crusting on the cheeks and extensor surfaces of the arms and legs. The diaper area is SPARED. Diagnosis?",', '["Seborrheic dermatitis", "Atopic dermatitis (Eczema)", "Candidiasis", "Scabies"]', 1, 'Infantile eczema typically affects the face and extensors, sparing the diaper area (due to the moisture barrier). It is highly pruritic. (Nelson)'),
    (v_topic_id, '224: A neonate develops honey-colored crusts over an erythematous base on the face. What is the most common organism and treatment?",', '["Streptococcus agalactiae; Penicillin", "Staphylococcus aureus; Topical Mupirocin", "Pseudomonas aeruginosa; Ciprofloxacin", "Herpes simplex; Acyclovir"]', 1, 'Non-bullous impetigo is most commonly caused by S. aureus or Strep pyogenes. Topical mupirocin is first-line for localized lesions. (First Aid)'),
    (v_topic_id, '225: A 5-day-old infant develops large, flaccid bullae in the diaper area and axillae. The bullae rupture easily, leaving raw, red skin. The Nikolsky sign is positive. The infant has a fever. Diagnosis?",', '["Bullous impetigo", "Staphylococcal Scalded Skin Syndrome (SSSS)", "Epidermolysis bullosa", "Stevens-Johnson Syndrome"]', 1, 'SSSS is caused by exfoliative toxins (ETA/ETB) produced by S. aureus, which cleave desmoglein-1 in the epidermis. Requires IV antibiotics (e.g., oxacillin, nafcillin). (Case Files)'),
    (v_topic_id, '226: A neonate is born with generalized blistering and erosions of the skin, particularly at sites of friction (e.g., from handling). The mucosal surfaces are also involved. What is the likely underlying defect?",', '["Staphylococcal toxin", "Autoantibodies against desmosomes", "Genetic defect in structural proteins (e.g., collagen VII or keratin) causing Epidermolysis Bullosa", "Herpes simplex virus"]', 2, 'Epidermolysis bullosa is a group of genetic mechanobullous disorders. The skin is incredibly fragile, blistering with minimal trauma. (UWorld)'),
    (v_topic_id, '227: A neonate presents with a small, self-limiting pustular rash on a hyperpigmented base present at birth. The pustules rupture easily, leaving a collarette of scale. A Wright stain of the pustule shows predominantly neutrophils. Diagnosis?",', '["Erythema Toxicum Neonatorum", "Transient Neonatal Pustular Melanosis", "Neonatal Herpes", "Milia"]', 1, 'Unlike erythema toxicum (which has eosinophils and appears at day 2-3), TNPM is present at birth, leaves hyperpigmented macules, and contains neutrophils. (Amboss)'),
    (v_topic_id, '228: A neonate is found to have a single, firm, red-purple nodule on the forearm. Over the next month, it rapidly enlarges. A biopsy shows proliferation of endothelial cells. What is the natural history of this lesion?",', '["It will undergo malignant transformation", "It will continue to grow throughout life", "It will rapidly involute within 6 months", "It will proliferate during the first year, then slowly involute over the next 5-10 years"]', 3, 'This describes an infantile hemangioma. (Nelson)'),
    (v_topic_id, '229: A neonate is born with a large, hairy, dark brown plaque over the lower back. What is the major long-term risk of this lesion?",', '["Development of malignant melanoma", "Underlying spina bifida", "Bleeding", "Infection"]', 0, 'Giant Congenital Melanocytic Nevi (>20 cm projected adult size) carry a significant lifetime risk of melanoma (approx. 5-10%) and require close dermatologic monitoring or prophylactic excision. (First Aid)'),
    (v_topic_id, '230: A newborn presents with a firm, yellowish, hairless plaque on the scalp. The pediatrician notes this lesion must be excised before adolescence. What is the diagnosis?",', '["Nevus sebaceous", "Epidermal nevus", "Alopecia areata", "Aplasia cutis congenita"]', 0, 'Nevus sebaceous carries a small risk of developing secondary neoplasms (e.g., basal cell carcinoma, trichoblastoma) during adolescence/adulthood, thus prophylactic excision is often recommended. (Case Files)'),
    (v_topic_id, '231: A neonate presents with a localized absence of skin on the scalp vertex, appearing as a punched-out, ulcerated lesion. Diagnosis?",', '["Aplasia cutis congenita", "Forceps injury", "Herpes simplex", "Epidermolysis bullosa"]', 0, 'Aplasia cutis congenita is a congenital absence of skin. It can be isolated or associated with Trisomy 13. (UWorld)'),
    (v_topic_id, '232: A newborn is noted to have a palpable, firm, solitary mass in the right flank. Ultrasound shows a multicystic mass replacing the right kidney. The left kidney is normal. What is the most common neonatal renal mass?",', '["Wilms tumor", "Neuroblastoma", "Multicystic Dysplastic Kidney (MCDK)", "Autosomal Recessive Polycystic Kidney Disease (ARPKD)"]', 2, 'MCDK is the most common cause of an abdominal mass in a newborn. It is a non-functioning kidney composed of cysts. If unilateral, the prognosis is excellent as the contralateral kidney hypertrophies. (Amboss)'),
    (v_topic_id, '233: A newborn presents with massive, bilateral flank masses, severe oligohydramnios in utero, and pulmonary hypoplasia. Ultrasound shows massively enlarged, echogenic kidneys with loss of corticomedullary differentiation. Diagnosis?",', '["Multicystic Dysplastic Kidney", "Autosomal Recessive Polycystic Kidney Disease (ARPKD)", "Autosomal Dominant Polycystic Kidney Disease (ADPKD)", "Bilateral Wilms tumor"]', 1, 'ARPKD presents in the neonatal period with massively enlarged kidneys, Potter sequence (from oligohydramnios), and is associated with congenital hepatic fibrosis. (Nelson)'),
    (v_topic_id, '234: A neonate is diagnosed with Autosomal Recessive Polycystic Kidney Disease (ARPKD). What non-renal organ system is always involved and requires long-term monitoring?",', '["Heart (cardiomyopathy)", "Liver (congenital hepatic fibrosis leading to portal hypertension)", "Brain (berry aneurysms)", "Lungs (cystic fibrosis)"]', 1, 'All patients with ARPKD have some degree of congenital hepatic fibrosis, which can lead to portal hypertension and variceal bleeding later in childhood. (First Aid)'),
    (v_topic_id, '235: A 1-month-old infant presents with a new-onset, firm, irregular abdominal mass that crosses the midline. They also have "raccoon eyes" (periorbital ecchymoses) and opsoclonus-myoclonus syndrome ("dancing eyes, dancing feet"). Diagnosis?",', '["Wilms tumor", "Neuroblastoma", "Hepatoblastoma", "Teratoma"]', 1, 'Neuroblastoma is a tumor of neural crest cells (sympathetic chain or adrenal medulla). It classically crosses the midline and has unique paraneoplastic syndromes (opsoclonus-myoclonus). (Case Files)'),
    (v_topic_id, '236: A 2-year-old child presents with a smooth, firm abdominal mass that does NOT cross the midline. The child is otherwise asymptomatic, though blood pressure is slightly elevated. Diagnosis?",', '["Neuroblastoma", "Wilms tumor (Nephroblastoma)", "Hepatoblastoma", "Lymphoma"]', 1, 'Wilms tumor classically presents in early childhood as a unilateral, smooth mass that does not cross the midline. It is the most common primary renal malignancy of childhood. (UWorld)'),
    (v_topic_id, '237: A newborn is diagnosed with WAGR syndrome. What does WAGR stand for?",', '["Wilms tumor, Aniridia, Genitourinary anomalies, Retardation (Intellectual disability)", "Weakness, Anemia, Growth failure, Renal failure", "White pupillary reflex, Ataxia, Glaucoma, Retinoblastoma", "None of the above"]', 0, 'Caused by a microdeletion of 11p13 (including the WT1 gene). Aniridia (absence of the iris) is a classic finding. (Amboss)'),
    (v_topic_id, '238: A neonate presents with a massive, firm mass extending from the sacrum and coccyx. It is diagnosed prenatally. What is this tumor?",', '["Sacrococcygeal teratoma", "Neuroblastoma", "Meningomyelocele", "Chordoma"]', 0, 'Sacrococcygeal teratoma is the most common germ cell tumor in neonates. It requires prompt surgical resection. Most are benign at birth but can undergo malignant transformation. (Nelson)'),
    (v_topic_id, '239: A newborn presents with profound hypotonia, poor feeding, and a weak cry. Genetic testing reveals a deletion on the maternally inherited chromosome 15q11-q13. The infant later develops inappropriate bouts of laughter and severe intellectual disability. Diagnosis?",', '["Prader-Willi Syndrome", "Angelman Syndrome", "Rett Syndrome", "Fragile X Syndrome"]', 1, 'Angelman syndrome is caused by the loss of the MATERNALLY contributed UBE3A gene. Known as the "happy puppet" syndrome. (First Aid)'),
    (v_topic_id, '240: A newborn female develops severe hypoglycemia, jaundice, and hepatomegaly. The mother mentions the baby had a seizure shortly after being fed apple juice by a relative. What is the enzyme deficiency?",', '["Galactose-1-phosphate uridyltransferase", "Aldolase B", "Fructokinase", "Glucose-6-phosphatase"]', 1, 'Hereditary Fructose Intolerance (Aldolase B deficiency) presents when fructose (fruit juice, table sugar) is introduced. It causes severe hypoglycemia and liver damage. (Case Files)'),
    (v_topic_id, '241: A neonate is entirely asymptomatic but their urine tests positive for reducing substances. Fructose is identified in the urine. Blood glucose is normal. Diagnosis?",', '["Hereditary Fructose Intolerance", "Essential Fructosuria", "Classic Galactosemia", "Diabetes Mellitus"]', 1, 'Essential fructosuria (Fructokinase deficiency) is a benign, asymptomatic condition where fructose is simply excreted in the urine. (UWorld)'),
    (v_topic_id, '242: A neonate presents with failure to thrive, diarrhea, and a severe diaper rash consisting of sharply demarcated, erythematous, scaling plaques around the mouth (periorificial) and anus. Diagnosis and underlying deficiency?",', '["Acrodermatitis enteropathica; Zinc deficiency", "Pellagra; Niacin deficiency", "Scurvy; Vitamin C deficiency", "Kwashiorkor; Protein deficiency"]', 0, 'Acrodermatitis enteropathica is a rare autosomal recessive defect in intestinal zinc absorption. (Amboss)'),
    (v_topic_id, '243: A neonate presents with a flat, red/purple birthmark on the nape of the neck ("stork bite") and on the glabella between the eyes. What is the prognosis for these lesions?",', '["They will require laser removal", "They are highly associated with intracranial anomalies", "The glabellar lesions typically fade by age 1-2, while the neck lesions often persist for life", "They will develop into raised hemangiomas"]', 2, 'Nevus simplex (salmon patch/stork bite) is a benign capillary malformation. Glabellar/eyelid lesions fade; nuchal lesions persist. (Nelson)'),
    (v_topic_id, '244: A neonate is born to a mother who actively used cocaine throughout pregnancy. The infant is at highest risk for which of the following complications?",', '["Macrosomia", "Placental abruption, prematurity, and low birth weight", "Congenital heart block", "Biliary atresia"]', 1, 'Cocaine causes severe vasoconstriction, leading to placental insufficiency, abruption, and IUGR. It is less likely to cause a specific teratogenic syndrome like alcohol or phenytoin. (First Aid)'),
    (v_topic_id, '245: A neonate presents with microcephaly, a smooth philtrum, thin upper lip, and short palpebral fissures. The infant is irritable and small for gestational age. Diagnosis?",', '["Fetal Alcohol Syndrome", "Fragile X Syndrome", "Williams Syndrome", "Neonatal Abstinence Syndrome"]', 0, 'Classic facial features of Fetal Alcohol Syndrome. Alcohol is a potent teratogen affecting brain development and causing midline facial anomalies. (Case Files)'),
    (v_topic_id, '246: A neonate presents with elfin facies, a cheerful demeanor, hypercalcemia, and a harsh systolic murmur radiating to the carotids. Diagnosis?",', '["Down Syndrome", "Williams Syndrome", "DiGeorge Syndrome", "Noonan Syndrome"]', 1, 'Williams Syndrome (7q11.23 microdeletion). The murmur is typically due to supravalvular aortic stenosis. The hypercalcemia often resolves in childhood. (UWorld)'),
    (v_topic_id, '247: A neonate is noted to have a short stature, webbed neck, pectus excavatum, and pulmonic stenosis. The karyotype is 46,XY. What syndrome shares many features with Turner syndrome but occurs in both males and females?",', '["Noonan Syndrome", "Klinefelter Syndrome", "Marfan Syndrome", "Ehlers-Danlos Syndrome"]', 0, 'Noonan syndrome is an autosomal dominant RASopathy. It has a Turner-like phenotype but features Right-sided heart lesions (Pulmonic stenosis), whereas Turner has Left-sided lesions (Coarctation, Bicuspid AoV). (Amboss)'),
    (v_topic_id, '248: A neonate presents with profound, intractable seizures starting on the first day of life. EEG shows a burst-suppression pattern. The infant has a defect in the KCNQ2 gene. What is the diagnosis?",', '["Benign Familial Neonatal Seizures", "Ohtahara Syndrome", "West Syndrome", "Lennox-Gastaut Syndrome"]', 1, 'Ohtahara syndrome (Early Infantile Epileptic Encephalopathy) presents with severe seizures and burst-suppression on EEG in the first weeks of life. Prognosis is very poor. (Nelson)'),
    (v_topic_id, '249: A 4-month-old infant presents with clusters of sudden, brief, symmetric muscle contractions (flexion of the head, trunk, and arms) occurring upon waking. EEG shows hypsarrhythmia. Diagnosis?",', '["Infantile Spasms (West Syndrome)", "Benign sleep myoclonus", "Absence seizures", "Generalized tonic-clonic seizures"]', 0, 'Infantile spasms are a severe epileptic encephalopathy. The classic triad is infantile spasms, developmental regression, and hypsarrhythmia on EEG. (First Aid)'),
    (v_topic_id, '250: What is the first-line medical treatment for Infantile Spasms (West Syndrome)?",', '["Phenobarbital", "Adrenocorticotropic hormone (ACTH) or oral corticosteroids (Vigabatrin is first-line if associated with Tuberous Sclerosis)", "Levetiracetam", "Ethosuximide"]', 1, 'ACTH/steroids are first-line. Vigabatrin is specifically preferred if the patient has Tuberous Sclerosis Complex. (Case Files)'),
    (v_topic_id, '251: A neonate is born completely covered in a thick, parchment-like membrane that cracks and peels over the first few weeks, revealing red skin underneath. Diagnosis?",', '["Collodion baby", "Harlequin ichthyosis", "Staphylococcal Scalded Skin Syndrome", "Epidermolysis bullosa"]', 0, 'A collodion baby is a presentation of several types of ichthyosis (e.g., lamellar ichthyosis). The primary risk is dehydration and infection as the membrane cracks. (UWorld)'),
    (v_topic_id, '252: A neonate is born with massive, thick, armor-like plates of scale with deep erythematous fissures. Ectropion (everted eyelids) and eclabium (everted lips) are severe. Diagnosis?",', '["Harlequin ichthyosis", "Collodion baby", "X-linked ichthyosis", "Ichthyosis vulgaris"]', 0, 'Harlequin ichthyosis is the most severe and often fatal form of ichthyosis, caused by a mutation in the ABCA12 lipid transporter. (Amboss)'),
    (v_topic_id, '253: A neonate has a small, benign tumor of the eye. Exam reveals a coloboma of the iris, anal atresia, and a preauricular skin tag. What syndrome is suspected?",', '["Cat Eye Syndrome", "VACTERL association", "CHARGE syndrome", "Treacher Collins syndrome"]', 0, 'Cat Eye Syndrome (Trisomy 22q11) presents with iris colobomas (giving a cat-eye appearance), anal atresia, and ear tags. (Nelson)'),
    (v_topic_id, '254: A neonate presents with choanal atresia, a coloboma of the retina, a ventricular septal defect, and profound hearing loss. What syndrome is this?",', '["CHARGE syndrome", "VACTERL association", "DiGeorge syndrome", "Waardenburg syndrome"]', 0, 'CHARGE: Coloboma, Heart defect, Atresia choanae, Retarded growth, Genitourinary anomalies, Ear anomalies/deafness. Caused by CHD7 mutation. (First Aid)'),
    (v_topic_id, '255: A neonate is born with a brilliant white forelock of hair, heterochromia iridis (differently colored eyes), and sensorineural deafness. Diagnosis?",', '["Waardenburg Syndrome", "Albinism", "Piebaldism", "Sturge-Weber syndrome"]', 0, 'Waardenburg syndrome is a neural crest defect affecting melanocytes. Melanocytes are required for normal stria vascularis function in the inner ear, hence the deafness. (Case Files)'),
    (v_topic_id, '256: A neonate presents with hypopigmentation of the skin, hair, and eyes, along with nystagmus and photophobia. What enzyme is deficient?",', '["Tyrosinase", "Phenylalanine hydroxylase", "Homogentisate oxidase", "Alpha-galactosidase"]', 0, 'Oculocutaneous albinism is most commonly caused by a deficiency of tyrosinase, preventing the conversion of tyrosine to melanin. (UWorld)'),
    (v_topic_id, '257: A neonate is found to have an absent radius bilaterally. Platelet count is 15,000/microL. What is the diagnosis?",', '["TAR (Thrombocytopenia-Absent Radius) Syndrome", "Fanconi anemia", "Diamond-Blackfan anemia", "Holt-Oram syndrome"]', 0, 'TAR syndrome features bilateral absent radii BUT present thumbs, distinguishing it from Fanconi anemia or Holt-Oram (where thumbs are absent/hypoplastic). (Amboss)'),
    (v_topic_id, '258: A neonate presents with a triphalangeal thumb, an atrial septal defect (ASD), and a normal platelet count. Diagnosis?",', '["Holt-Oram Syndrome", "TAR syndrome", "Fanconi anemia", "VACTERL association"]', 0, 'Holt-Oram (Heart-Hand) syndrome is an autosomal dominant disorder causing upper limb defects and cardiac septal defects. (Nelson)'),
    (v_topic_id, '259: A 2-month-old infant presents with profound anemia (Hb 4.0), reticulocytopenia, and macrocytosis. White blood cells and platelets are normal. The infant has a triphalangeal thumb and a webbed neck. Diagnosis?",', '["Diamond-Blackfan Anemia", "Fanconi anemia", "Transient erythroblastopenia of childhood", "Parvovirus B19 infection"]', 0, 'Diamond-Blackfan is a pure red cell aplasia presenting in the first year of life. It is often associated with physical anomalies like thumb defects and webbed neck. (First Aid)'),
    (v_topic_id, '260: A neonate develops profound hypoglycemia within 30 minutes of birth. They are macrosomic, have a large tongue, and an omphalocele. What is the mechanism of the hypoglycemia?",', '["Hyperinsulinism due to pancreatic islet cell hyperplasia", "Glycogen storage disease", "Defective gluconeogenesis", "Galactosemia"]', 0, 'In Beckwith-Wiedemann syndrome, there is marked hyperinsulinemia leading to severe, refractory neonatal hypoglycemia. (Case Files)'),
    (v_topic_id, '261: A neonate is diagnosed with transient tachypnea of the newborn (TTN). What is the classic finding on chest radiograph?",', '["Prominent perihilar streaking, fluid in the interlobar fissures, and hyperinflation", "Diffuse ground-glass opacities with air bronchograms", "Patchy infiltrates and severe hyperinflation", "Pneumatosis intestinalis"]', 0, 'TTN radiograph findings reflect retained fluid in the lymphatic and venous structures of the lung. (UWorld)'),
    (v_topic_id, '262: A premature infant is born at 28 weeks. To prevent Intraventricular Hemorrhage (IVH), what is a key management strategy in the first few days of life?",', '["Maintain stable cerebral hemodynamics by avoiding rapid fluid boluses and swings in blood pressure", "Administer prophylactic IV Indomethacin", "Administer high-dose heparin", "Perform daily lumbar punctures"]', 0, 'The germinal matrix is highly sensitive to fluctuations in cerebral blood flow. Careful fluid and blood pressure management is the most effective prevention. (Amboss)'),
    (v_topic_id, '263: A neonate presents with a continuous machinery murmur, bounding pulses, and signs of heart failure. Echocardiogram confirms a large PDA. Which condition is a CONTRAINDICATION to medical closure of the PDA with Indomethacin?",', '["Ductal-dependent cardiac lesions, active bleeding (e.g., IVH), or significant renal impairment", "Prematurity", "Low birth weight", "Respiratory distress syndrome"]', 0, 'Indomethacin decreases renal blood flow and inhibits platelet aggregation. It must not be used if the PDA is keeping the infant alive (e.g., Coarctation of the aorta). (Nelson)'),
    (v_topic_id, '264: A neonate is born to a mother with Hepatitis B (HBsAg positive). What is the required post-exposure prophylaxis for the infant?",', '["Hepatitis B vaccine and Hepatitis B Immune Globulin (HBIG) within 12 hours of birth", "Hepatitis B vaccine only", "HBIG only", "Start lamivudine therapy"]', 0, 'Dual therapy (active and passive immunization) is highly effective at preventing vertical transmission of HBV. (First Aid)'),
    (v_topic_id, '265: A mother with HIV asks if she can breastfeed her newborn. In the United States (or other developed countries where safe alternatives exist), what is the recommendation?",', '["Breastfeeding is contraindicated to prevent vertical transmission of HIV", "Breastfeeding is encouraged if her viral load is undetectable", "Breastfeeding is allowed if the infant is on ARVs", "Boil the breast milk first"]', 0, 'In developed countries with safe water and formula, HIV is an absolute contraindication to breastfeeding, regardless of viral load. (Case Files)'),
    (v_topic_id, '266: What is the most common cause of ambiguous genitalia in a 46,XX neonate?",', '["Congenital Adrenal Hyperplasia (21-hydroxylase deficiency)", "Exogenous maternal androgens", "Aromatase deficiency", "Ovotesticular DSD"]', 0, 'CAH is the overwhelming majority of cases of 46,XX virilization. (UWorld)'),
    (v_topic_id, '267: A neonate presents with a large, fluid-filled cystic mass over the occiput. It transilluminates. Underlying brain tissue is not within the sac. Diagnosis?",', '["Cranial meningocele", "Encephalocele", "Cystic hygroma", "Caput succedaneum"]', 0, 'A meningocele contains meninges and CSF but no neural tissue. An encephalocele contains brain tissue. (Amboss)'),
    (v_topic_id, '268: A neonate presents with a tuft of hair on the lower back. What is the embryologic failure?",', '["Failure of the caudal neuropore to close", "Failure of the rostral neuropore to close", "Failure of neural crest migration", "Failure of somite formation"]', 0, 'Spina bifida (occulta or cystica) is due to failure of the caudal neuropore to close at day 27 of gestation. Failure of the rostral neuropore causes anencephaly. (Nelson)'),
    (v_topic_id, '269: A newborn infant passes a meconium stool that is thick and gray-white (acholic) rather than the normal dark green-black. What diagnosis must be strongly considered?",', '["Biliary atresia or severe cholestasis", "Meconium ileus", "Normal variation", "Gastrointestinal bleeding"]', 0, 'Meconium is green due to bile pigments. White meconium suggests severe intrauterine biliary obstruction. (First Aid)'),
    (v_topic_id, '270: A neonate presents with severe hypotonia, a weak cry, and absent deep tendon reflexes. The mother has a history of grip myotonia and cataracts. Diagnosis?",', '["Congenital Myotonic Dystrophy", "Spinal Muscular Atrophy", "Neonatal Myasthenia Gravis", "Botulism"]', 0, 'Congenital myotonic dystrophy (CTG repeat expansion) presents with severe hypotonia. The mother''s history is the key clue. Anticipation causes the congenital form to be severe. (Case Files)'),
    (v_topic_id, '271: A neonate is born to a mother with Myasthenia Gravis. The infant presents with transient hypotonia, weak cry, and poor feeding that resolves over 2-4 weeks. Pathophysiology?",', '["Transplacental transfer of maternal anti-acetylcholine receptor antibodies", "Genetic inheritance of mutated AChR", "Botulinum toxin exposure", "Spinal cord injury"]', 0, 'Transient Neonatal Myasthenia Gravis occurs as maternal IgG antibodies cross the placenta. As the antibodies degrade over a few weeks, the infant recovers completely. (UWorld)'),
    (v_topic_id, '272: A neonate presents with a heart rate of 250 bpm, narrow QRS complexes, and absent P waves. The infant is poorly perfused. Diagnosis?",', '["Supraventricular Tachycardia (SVT)", "Sinus Tachycardia", "Ventricular Tachycardia", "Atrial Fibrillation"]', 0, 'SVT is the most common significant tachyarrhythmia in neonates. Rates >220 in infants suggest SVT. (Amboss)'),
    (v_topic_id, '273: What is the first-line medical therapy for a hemodynamically stable neonate with Supraventricular Tachycardia (SVT)?",', '["Vagal maneuvers (e.g., application of ice to the face), followed by rapid IV Adenosine", "Synchronized cardioversion", "IV Amiodarone", "Defibrillation"]', 0, 'Ice to the face stimulates the diving reflex (vagal tone). If that fails, Adenosine rapidly blocks the AV node. (Nelson)'),
    (v_topic_id, '274: A neonate is born via C-section. Upon emerging, the infant takes a gasp and develops a pneumothorax. What is the most appropriate management for a small, asymptomatic pneumothorax in a term infant?",', '["Observation and administration of 100% oxygen (nitrogen washout)", "Immediate chest tube placement", "Needle thoracostomy", "Intubation"]', 0, 'Small, asymptomatic pneumothoraces often resolve on their own. Breathing 100% O2 creates a nitrogen gradient that speeds the absorption of the trapped air. (First Aid)'),
    (v_topic_id, '275: A neonate is diagnosed with polycythemia. They develop bloody stools, abdominal distension, and feeding intolerance. What complication has occurred?",', '["Necrotizing Enterocolitis (NEC)", "Intussusception", "Volvulus", "Anal fissure"]', 0, 'Hyperviscosity from polycythemia leads to sluggish mesenteric blood flow and bowel ischemia, greatly increasing the risk of NEC, even in term infants. (Case Files)'),
    (v_topic_id, '276: A neonate presents with a small, red, benign, capillary hemangioma on the eyelid causing ptosis and obstructing the visual axis. What is the treatment?",', '["Oral propranolol", "Observation", "Topical antibiotics", "Surgical excision"]', 0, 'Hemangiomas obstructing vision must be treated promptly to prevent deprivation amblyopia (permanent vision loss). Propranolol is first-line. (UWorld)'),
    (v_topic_id, '277: A neonate develops a hard, firm, non-tender nodule in the subcutaneous tissue of the cheek after a cold exposure (e.g., an ice pack was applied). Diagnosis?",', '["Subcutaneous fat necrosis of the newborn", "Erythema nodosum", "Cellulitis", "Hemangioma"]', 0, 'A benign, self-limiting panniculitis that occurs after perinatal stress, cold exposure, or trauma. (Amboss)'),
    (v_topic_id, '278: What potentially life-threatening metabolic derangement is associated with Subcutaneous Fat Necrosis of the newborn?",', '["Hypercalcemia", "Hypocalcemia", "Hypoglycemia", "Hyperkalemia"]', 0, 'Macrophages in the granulomatous infiltrate produce 1,alpha-hydroxylase, increasing 1,25-OH Vitamin D and leading to delayed hypercalcemia. (Nelson)'),
    (v_topic_id, '279: A neonate has a single, large, cafe-au-lait spot. Is this diagnostic of Neurofibromatosis Type 1?",', '["No, >6 spots are required for diagnosis", "Yes", "Yes, if it is larger than 15mm", "No, it indicates McCune-Albright"]', 0, 'A single spot is common and benign. Diagnosis of NF1 requires at least 6 macules (>5mm in prepubertal, >15mm in postpubertal), plus other criteria. (First Aid)'),
    (v_topic_id, '280: A newborn presents with a unilateral port-wine stain over the V1 ophthalmic branch of the trigeminal nerve. What ophthalmologic condition must be screened for?",', '["Glaucoma", "Cataracts", "Retinoblastoma", "Strabismus"]', 0, 'Sturge-Weber syndrome involves capillary-venous malformations in the eye, leading to increased intraocular pressure and glaucoma. (Case Files)'),
    (v_topic_id, '281: A neonate presents with microcephaly, sensorineural hearing loss, and periventricular calcifications. The mother had a mild, mononucleosis-like illness during the first trimester. Diagnosis?",', '["Congenital Cytomegalovirus (CMV)", "Congenital Toxoplasmosis", "Congenital Rubella", "Congenital Syphilis"]', 0, 'CMV is the most common congenital infection. It often presents with periventricular calcifications, whereas toxoplasmosis causes diffuse/parenchymal calcifications. (Amboss)'),
    (v_topic_id, '282: What is the recommended treatment for a symptomatic neonate with congenital CMV infection involving the CNS?",', '["Oral Valganciclovir or IV Ganciclovir for 6 months", "Oral Acyclovir for 14 days", "IV Penicillin G", "Supportive care only"]', 0, 'Antiviral therapy (valganciclovir/ganciclovir) is indicated for symptomatic congenital CMV to improve neurodevelopmental and audiologic outcomes. (Nelson)'),
    (v_topic_id, '283: A newborn presents with a maculopapular rash on the palms and soles, hepatosplenomegaly, and copious rhinorrhea ("snuffles"). What is the next best diagnostic step?",', '["RPR/VDRL and Treponemal specific testing (e.g., FTA-ABS) of the infant and mother", "Viral culture of the rhinorrhea", "Urine CMV PCR", "Blood culture for GBS"]', 0, 'These are classic signs of congenital syphilis. Both non-treponemal and treponemal tests are required to confirm the diagnosis and distinguish it from passive transfer of maternal antibodies. (First Aid)'),
    (v_topic_id, '284: A neonate is born to a mother with active secondary syphilis. The neonate is asymptomatic. Evaluation shows the neonate''s RPR titer is 1:32 and the mother''s is 1:4. What is the interpretation and management?",', '["The infant has congenital syphilis (infant titer > 4x maternal titer); treat with IV Aqueous Penicillin G", "Passive transfer of antibodies; no treatment needed", "Inconclusive; repeat in 1 month", "False positive; recheck with FTA-ABS"]', 0, 'An infant RPR titer that is fourfold or greater than the maternal titer is diagnostic of congenital syphilis, requiring a 10-day course of IV penicillin. (UWorld)'),
    (v_topic_id, '285: A neonate is born at 34 weeks and develops copious, purulent eye discharge at day 3 of life. Gram stain reveals gram-negative intracellular diplococci. What is the most serious complication of this infection if left untreated?",', '["Corneal ulceration and permanent blindness", "Chlamydial pneumonia", "Viral encephalitis", "Sensorineural hearing loss"]', 0, 'Gonococcal ophthalmia neonatorum is a medical emergency because the bacteria can rapidly penetrate the intact cornea, causing ulceration, perforation, and blindness. (Case Files)'),
    (v_topic_id, '286: A 2-week-old infant presents with tachypnea, a "staccato" cough, and no fever. Chest X-ray shows hyperinflation and diffuse interstitial infiltrates. The infant had mild conjunctivitis at day 10 of life. What is the diagnosis?",', '["Chlamydia trachomatis pneumonia", "Respiratory Syncytial Virus (RSV) bronchiolitis", "Bordetella pertussis", "Neonatal RDS"]', 0, 'Chlamydia pneumonia classically presents between 2 and 12 weeks of life with an afebrile, staccato cough, often preceded by conjunctivitis. Treated with oral macrolides. (Amboss)'),
    (v_topic_id, '287: A neonate is evaluated for poor feeding and lethargy. A blood culture grows Listeria monocytogenes. What is the appropriate antibiotic coverage?",', '["Ampicillin and Gentamicin", "Vancomycin and Cefotaxime", "Acyclovir", "Erythromycin"]', 0, 'Listeria is intrinsically resistant to cephalosporins. Ampicillin is the drug of choice, often synergized with gentamicin for neonatal sepsis/meningitis. (Nelson)'),
    (v_topic_id, '288: A 10-day-old neonate presents with fever, irritability, a bulging fontanelle, and poor feeding. CSF analysis shows elevated WBCs (predominantly neutrophils), low glucose, and high protein. What is the most common cause of neonatal meningitis?",', '["Group B Streptococcus (GBS)", "Streptococcus pneumoniae", "Neisseria meningitidis", "Haemophilus influenzae type b"]', 0, 'GBS is the most common cause of both neonatal sepsis and neonatal meningitis, followed by E. coli and Listeria. (First Aid)'),
    (v_topic_id, '289: A term infant is born to a mother with a history of genital HSV. At delivery, the mother has NO active lesions or prodromal symptoms. What is the appropriate management of the infant?",', '["Routine care; observe closely and educate parents on signs of infection", "Immediate IV Acyclovir", "Perform surface swabs on the infant for HSV PCR immediately after birth", "Cesarean delivery is strictly required even if no lesions are present"]', 0, 'If there are no active lesions or prodrome at the onset of labor, vaginal delivery is safe, and the infant only requires routine care and close observation. Swabs (if done) should be delayed until 24 hours of life to avoid detecting transient maternal flora. (UWorld)'),
    (v_topic_id, '290: A neonate is diagnosed with disseminated HSV infection, presenting with sepsis, liver failure, and DIC. What is the mortality rate of untreated disseminated neonatal HSV?",', '["< 10%", "25%", "50%", "> 80%"]', 3, 'Untreated disseminated neonatal HSV is rapidly fatal in > 80% of cases. Even with IV acyclovir therapy, mortality and neurologic morbidity remain high. (Case Files)'),
    (v_topic_id, '291: A premature infant (28 weeks) is tolerating enteral feeds when they suddenly develop bilious emesis, a distended, shiny abdomen, and grossly bloody stools. Abdominal X-ray shows air in the portal venous system. Diagnosis?",', '["Necrotizing Enterocolitis (NEC)", "Malrotation with volvulus", "Intussusception", "Meconium ileus"]', 0, 'Portal venous gas and pneumatosis intestinalis are the radiologic hallmarks of NEC. Portal gas is an advanced sign of bowel necrosis. (Amboss)'),
    (v_topic_id, '292: What maternal practice has been shown to significantly DECREASE the risk of Necrotizing Enterocolitis (NEC) in premature infants?",', '["Provision of human breast milk (mother''s own milk or pasteurized donor milk)", "Use of broad-spectrum prophylactic antibiotics", "Delaying enteral feeds until 34 weeks corrected age", "Use of soy-based formulas"]', 0, 'Human milk contains IgA, lactoferrin, and prebiotics that promote healthy gut flora and mucosal integrity, drastically reducing the incidence of NEC compared to bovine formula. (Nelson)'),
    (v_topic_id, '293: A newborn infant with Trisomy 21 presents with bilious emesis. An abdominal X-ray shows a "double-bubble" sign. The parents ask if surgery is an absolute emergency. What is the correct response?",', '["No, duodenal atresia is not a surgical emergency. The infant must first be stabilized, decompressed, and evaluated for cardiac defects.", "Yes, it must be repaired within 2 hours to prevent bowel necrosis.", "No, it will resolve spontaneously with time.", "Yes, otherwise the stomach will rupture."]', 0, 'Unlike malrotation with volvulus, duodenal atresia is a static obstruction without compromised blood supply. Surgery is elective and should follow a thorough cardiac evaluation (given the high association with AV canal defects). (First Aid)'),
    (v_topic_id, '294: A 4-week-old first-born male infant presents with non-bilious, forceful vomiting immediately after feeding. He is hungry and eager to feed again. A firm, mobile, 2 cm mass is palpated in the right upper quadrant. Diagnosis?",', '["Pyloric Stenosis", "Gastroesophageal Reflux Disease (GERD)", "Duodenal atresia", "Malrotation"]', 0, 'Hypertrophic pyloric stenosis typically presents between 3 and 6 weeks of life. The "olive" mass is pathognomonic. (UWorld)'),
    (v_topic_id, '295: What is the preferred diagnostic imaging modality for Hypertrophic Pyloric Stenosis?",', '["Abdominal Ultrasound", "Upper GI contrast series", "Abdominal X-ray", "CT scan"]', 0, 'Ultrasound is highly sensitive and specific, demonstrating a thickened and elongated pyloric muscle without exposing the infant to radiation. (Case Files)'),
    (v_topic_id, '296: An infant with pyloric stenosis has a pH of 7.55, Cl of 88, and K of 2.8. What is the most critical step BEFORE proceeding with surgical pyloromyotomy?",', '["Intravenous fluid resuscitation to correct the dehydration, hypochloremia, and hypokalemic metabolic alkalosis", "Immediate intubation", "Placement of a transpyloric feeding tube", "Administering IV antibiotics"]', 0, 'Pyloric stenosis is a MEDICAL emergency, not a surgical one. The severe metabolic alkalosis increases the risk of postoperative apnea. The infant must be completely resuscitated and electrolytes normalized before anesthesia. (Amboss)'),
    (v_topic_id, '297: A neonate presents with a scaphoid abdomen and severe respiratory distress. Bag-mask ventilation is initiated, but the infant rapidly deteriorates. Why is bag-mask ventilation contraindicated in this specific condition?",', '["It inflates the stomach and intestines that are herniated into the chest, further compressing the hypoplastic lungs", "It causes vocal cord paralysis", "It forces meconium deeper into the lungs", "It causes immediate cardiac arrest due to vagal stimulation"]', 0, 'In Congenital Diaphragmatic Hernia, air pumped into the stomach via bag-mask will expand the herniated bowel in the thorax, fatally compressing the remaining functional lung tissue. Immediate intubation is required. (Nelson)'),
    (v_topic_id, '298: A neonate is diagnosed with a Congenital Diaphragmatic Hernia (CDH). What is the primary cause of mortality in these infants?",', '["Pulmonary hypoplasia and persistent pulmonary hypertension", "Bowel ischemia/necrosis", "Sepsis", "Heart failure due to cardiac compression"]', 0, 'The herniated bowel prevents the ipsilateral (and often contralateral) lung from developing normally in utero, leading to severe pulmonary hypoplasia and extremely reactive pulmonary vasculature (PPHN). (First Aid)'),
    (v_topic_id, '299: A neonate is born via spontaneous vaginal delivery. A few hours later, a swelling is noted on the scalp. It is soft, boggy, and CROSSES the sagittal suture. Diagnosis?",', '["Caput succedaneum", "Cephalohematoma", "Subgaleal hemorrhage", "Skull fracture"]', 0, 'Caput succedaneum ("SUCCedaneum = SUbCutaneous") is superficial edema that freely crosses suture lines. It is benign. (UWorld)'),
    (v_topic_id, '300: A neonate is born via vacuum extraction. Hours later, the infant develops a rapidly expanding scalp swelling that crosses suture lines and pushes the ears forward. The infant is tachycardic, hypotensive, and has a dropping hematocrit. Diagnosis?",', '["Subgaleal hemorrhage", "Cephalohematoma", "Caput succedaneum", "Subarachnoid hemorrhage"]', 0, 'Subgaleal hemorrhage is bleeding beneath the epicranial aponeurosis. It is a massive potential space; an infant can exsanguinate into this space. It is a life-threatening emergency. (Case Files)'),
    (v_topic_id, '301: A neonate is born weighing 4.8 kg (macrosomic) after a shoulder dystocia. The infant''s right arm hangs limply at the side, internally rotated, with the elbow extended and forearm pronated. The grasp reflex is INTACT. Diagnosis?",', '["Erb-Duchenne palsy (C5-C6)", "Klumpke palsy (C8-T1)", "Clavicle fracture", "Spinal cord injury"]', 0, 'Erb palsy (waiter''s tip) affects the upper brachial plexus. The intact grasp reflex confirms the lower plexus (C8-T1) is spared. (Amboss)'),
    (v_topic_id, '302: What is the prognosis and management for a typical Erb-Duchenne palsy?",', '["Most recover spontaneously within 3-6 months; manage with observation and gentle physical therapy", "Requires immediate surgical nerve grafting", "Permanent paralysis is inevitable", "Immobilize the arm in a cast for 6 weeks"]', 0, 'Most cases represent neuropraxia (nerve stretch without avulsion) and recover fully with conservative management. Surgery is considered if no improvement by 3-6 months. (Nelson)'),
    (v_topic_id, '303: A neonate presents with a total absence of the right pectoralis major muscle and syndactyly of the right hand. Diagnosis?",', '["Poland Syndrome", "Apert Syndrome", "Erb Palsy", "Holt-Oram Syndrome"]', 0, 'Poland syndrome is characterized by unilateral absence/hypoplasia of the pectoralis major muscle and ipsilateral upper extremity anomalies (e.g., syndactyly). (First Aid)'),
    (v_topic_id, '304: A premature infant (25 weeks) undergoes a screening cranial ultrasound at 1 week of life. It shows hemorrhage in the germinal matrix that extends into the ventricles AND into the surrounding brain parenchyma. What grade IVH is this?",', '["Grade IV", "Grade I", "Grade II", "Grade III"]', 0, 'Grade IV is the most severe form of Intraventricular Hemorrhage, involving parenchymal extension (venous infarction). It carries a high risk of cerebral palsy and developmental delay. (UWorld)'),
    (v_topic_id, '305: A neonate born at 24 weeks gestation requires prolonged mechanical ventilation and high concentrations of oxygen. An eye exam at 4 weeks of age reveals abnormal neovascularization of the retina. Diagnosis?",', '["Retinopathy of Prematurity (ROP)", "Congenital Glaucoma", "Retinoblastoma", "Cytomegalovirus Retinitis"]', 0, 'ROP is driven by the transition from a hyperoxic environment (supplemental O2 suppressing VEGF) back to a relatively hypoxic state, causing a massive surge in VEGF and chaotic vessel growth. (Case Files)'),
    (v_topic_id, '306: What is the treatment for severe Retinopathy of Prematurity (ROP) (e.g., Plus disease) to prevent retinal detachment and blindness?",', '["Laser photocoagulation or intravitreal anti-VEGF therapy (e.g., bevacizumab)", "Topical corticosteroids", "Observation only", "Surgical enucleation"]', 0, 'Laser therapy ablates the avascular retina to decrease VEGF production. Anti-VEGF injections directly neutralize the factor. (Amboss)'),
    (v_topic_id, '307: A neonate presents with profound cyanosis within hours of birth. Echocardiogram reveals the aorta arising from the right ventricle and the pulmonary artery arising from the left ventricle. What is the diagnosis?",', '["Transposition of the Great Arteries (TGA)", "Tetralogy of Fallot", "Truncus Arteriosus", "Total Anomalous Pulmonary Venous Return"]', 0, 'TGA is the most common cyanotic lesion presenting in the immediate neonatal period. It creates two parallel, non-mixing circulations. (Nelson)'),
    (v_topic_id, '308: In a neonate with Transposition of the Great Arteries, what naturally occurring fetal structure is REQUIRED for initial survival before medical intervention?",', '["Patent Ductus Arteriosus (PDA) or a Ventricular/Atrial Septal Defect to allow mixing of blood", "Ligamentum arteriosum", "Ductus venosus", "Umbilical artery"]', 0, 'Without a shunt (PDA, VSD, or ASD/PFO), the parallel circuits cannot mix, and the infant will die of profound hypoxia immediately. PGE1 is given to keep the PDA open. (First Aid)'),
    (v_topic_id, '309: A 2-day-old infant is diagnosed with Transposition of the Great Arteries. The PDA is kept open with PGE1, but the infant remains severely cyanotic because the mixing across the PDA is insufficient. What is the next emergent life-saving procedure before definitive surgical repair?",', '["Balloon Atrial Septostomy (Rashkind procedure)", "Arterial switch operation", "Blalock-Taussig shunt", "Fontan procedure"]', 0, 'A balloon atrial septostomy tears the atrial septum, creating a large ASD to allow vital mixing of oxygenated and deoxygenated blood. (UWorld)'),
    (v_topic_id, '310: A neonate presents with a harsh holosystolic murmur at the left lower sternal border. Echocardiogram shows a defect in the ventricular septum. What is the most common type of Ventricular Septal Defect (VSD)?",', '["Perimembranous VSD", "Muscular VSD", "Inlet VSD", "Outlet/Supracristal VSD"]', 0, 'Perimembranous VSDs account for about 80% of all VSDs. They are located in the membranous portion of the septum, near the aortic and tricuspid valves. (Case Files)'),
    (v_topic_id, '311: A neonate is diagnosed with a small, restrictive VSD. What is the most likely physical exam finding regarding the murmur?",', '["A loud, harsh holosystolic murmur with a palpable thrill", "A soft, barely audible murmur", "A continuous machinery murmur", "A diastolic rumble"]', 0, 'Small VSDs have a very high pressure gradient across a small hole, creating immense turbulence and a very LOUD murmur. Large VSDs often have softer murmurs. (Amboss)'),
    (v_topic_id, '312: A premature infant (26 weeks) presents with bounding pulses, a widened pulse pressure, and a continuous machine-like murmur at the left infraclavicular region. Diagnosis?",', '["Patent Ductus Arteriosus (PDA)", "Coarctation of the Aorta", "Aortic Stenosis", "Pulmonary Stenosis"]', 0, 'Classic presentation of a PDA in a premature infant. The lack of ductal smooth muscle and low oxygen tension prevents normal closure. (Nelson)'),
    (v_topic_id, '313: A term neonate is born with severe cyanosis. Echocardiogram shows failure of the tricuspid valve to form, resulting in no communication between the right atrium and right ventricle. Diagnosis?",', '["Tricuspid Atresia", "Pulmonary Atresia", "Ebstein Anomaly", "Tetralogy of Fallot"]', 0, 'Tricuspid atresia requires an ASD (for right-to-left shunting to the LV) and a VSD (for left-to-right shunting back to the pulmonary artery) to survive. (First Aid)'),
    (v_topic_id, '314: A neonate presents with severe heart failure. Echocardiogram shows a single great vessel arising from the heart that supplies both the systemic and pulmonary circulations, overriding a large VSD. Diagnosis?",', '["Truncus Arteriosus", "Transposition of the Great Arteries", "Tetralogy of Fallot", "Double Outlet Right Ventricle"]', 0, 'Failure of the truncus arteriosus to divide into the aorta and pulmonary artery. It is strongly associated with DiGeorge syndrome (22q11 deletion). (UWorld)'),
    (v_topic_id, '315: A newborn female presents with ambiguous genitalia (clitoromegaly, fused labia). Labs show hyponatremia, hyperkalemia, and elevated 17-hydroxyprogesterone. Diagnosis?",', '["21-hydroxylase deficiency (Congenital Adrenal Hyperplasia)", "11-beta-hydroxylase deficiency", "5-alpha-reductase deficiency", "Complete Androgen Insensitivity Syndrome"]', 0, 'Classic salt-wasting CAH. The lack of aldosterone causes the electrolyte abnormalities. The buildup of precursors shunts to androgen synthesis, virilizing the female. (Case Files)'),
    (v_topic_id, '316: A newborn male presents with normal male genitalia but develops profound lethargy, vomiting, hyponatremia, and hyperkalemia at 2 weeks of life. 17-OHP is elevated. Diagnosis?",', '["Salt-wasting 21-hydroxylase deficiency (CAH) in a male", "Pyloric stenosis", "Adrenal hemorrhage", "Sepsis"]', 0, 'Males with CAH do not have ambiguous genitalia at birth (they are appropriately virilized), so the diagnosis is often missed until they present in a life-threatening adrenal (salt-wasting) crisis. (Amboss)'),
    (v_topic_id, '317: A newborn female presents with ambiguous genitalia and hypertension. Potassium is low. What is the enzyme deficiency?",', '["11-beta-hydroxylase deficiency", "21-hydroxylase deficiency", "17-alpha-hydroxylase deficiency", "Aromatase deficiency"]', 0, '11-beta deficiency blocks cortisol and aldosterone, but leads to a buildup of 11-deoxycorticosterone, which is a weak mineralocorticoid. This causes sodium retention, hypertension, and hypokalemia. Androgens are still overproduced, causing virilization. (Nelson)'),
    (v_topic_id, '318: A newborn presents with poor feeding, lethargy, and an enlarged liver. Blood glucose is 30 mg/dL. Urine ketones are NEGATIVE. What metabolic pathway is defective?",', '["Fatty acid oxidation (e.g., MCAD deficiency)", "Glycogenolysis (e.g., Von Gierke disease)", "Gluconeogenesis", "Galactose metabolism"]', 0, 'Hypoketotic hypoglycemia is the hallmark of fatty acid oxidation defects like Medium-Chain Acyl-CoA Dehydrogenase (MCAD) deficiency. The body cannot break down fats for energy, so it uses up glucose, but cannot produce ketones as a byproduct. (First Aid)'),
    (v_topic_id, '319: A neonate presents with a mousy odor, eczema, and microcephaly. Newborn screen was positive. What amino acid must be strictly restricted from the diet?",', '["Phenylalanine", "Tyrosine", "Leucine", "Methionine"]', 0, 'Phenylketonuria (PKU). Phenylalanine cannot be converted to tyrosine. (UWorld)'),
    (v_topic_id, '320: A neonate presents with sweet-smelling urine, lethargy, and poor feeding. What branched-chain amino acids are accumulating?",', '["Isoleucine, Leucine, Valine", "Phenylalanine, Tyrosine", "Methionine, Homocysteine", "Arginine, Lysine"]', 0, 'Maple Syrup Urine Disease (MSUD). "I Love Vermont maple syrup" = Isoleucine, Leucine, Valine. (Case Files)'),
    (v_topic_id, '321: A term infant presents with profound hypotonia and a weak cry. Deep tendon reflexes are absent. The tongue shows fasciculations. What gene is mutated in this autosomal recessive disorder?",', '["SMN1 (Survival Motor Neuron 1)", "DMD (Dystrophin)", "FMR1 (Fragile X)", "CFTR (Cystic Fibrosis)"]', 0, 'Spinal Muscular Atrophy (SMA) Type 1 (Werdnig-Hoffmann). Lack of SMN protein leads to apoptosis of lower motor neurons in the anterior horn of the spinal cord. (Amboss)'),
    (v_topic_id, '322: A newborn is found to have a cystic mass on the back of the neck. Karyotype shows 45,X. What is the mass?",', '["Cystic hygroma", "Thyroglossal duct cyst", "Branchial cleft cyst", "Meningocele"]', 0, 'Cystic hygromas are cavernous lymphangiomas. They are classically associated with Turner syndrome. (Nelson)'),
    (v_topic_id, '323: A newborn male presents with cryptorchidism, learning disabilities, and tall stature later in life. Karyotype is 47,XXY. Diagnosis?",', '["Klinefelter Syndrome", "Turner Syndrome", "Marfan Syndrome", "Fragile X Syndrome"]', 0, 'Klinefelter syndrome. They have testicular dysgenesis, leading to low testosterone, elevated FSH/LH, and infertility. (First Aid)'),
    (v_topic_id, '324: A neonate presents with a loud, harsh systolic murmur. Echocardiogram shows a thickened, dysplastic aortic valve with a narrow opening. What is the most common associated valvular anomaly if the patient also has Coarctation of the Aorta?",', '["Bicuspid Aortic Valve", "Mitral Valve Prolapse", "Ebstein Anomaly", "Tricuspid Atresia"]', 0, 'Over 50% of patients with coarctation of the aorta have a bicuspid aortic valve. (UWorld)'),
    (v_topic_id, '325: A newborn has a large, red, raised strawberry hemangioma on the chest. The parents are anxious. What is the most appropriate advice?",', '["The lesion will likely grow over the first year of life and then slowly shrink and fade on its own by age 5-10.", "It requires immediate surgical excision.", "It is a sign of an underlying malignancy.", "It will never go away and will require laser therapy."]', 0, 'Infantile hemangiomas have a classic course of rapid proliferation followed by spontaneous involution. Unless they obstruct vision or the airway, observation is best. (Case Files)'),
    (v_topic_id, '326: A neonate presents with a port-wine stain over the right leg. The right leg is significantly longer and thicker than the left leg. Diagnosis?",', '["Klippel-Trenaunay Syndrome", "Sturge-Weber Syndrome", "Neurofibromatosis Type 1", "Proteus Syndrome"]', 0, 'Klippel-Trenaunay syndrome involves a triad of capillary malformations (port-wine stains), venous malformations, and limb hypertrophy. (Amboss)'),
    (v_topic_id, '327: A neonate is born to a mother with gestational diabetes. The infant is macrosomic and develops jitteriness at 2 hours of life. Bedside glucose is 25 mg/dL. The infant is asymptomatic otherwise. First step?",', '["Feed the infant breast milk or formula and recheck glucose in 30 minutes", "Give IV D10W bolus", "Administer Glucagon", "Observation"]', 0, 'Enteral feeding is the first-line treatment for mild, asymptomatic hypoglycemia in a neonate. (Nelson)'),
    (v_topic_id, '328: A neonate with severe hypoglycemia (glucose 15 mg/dL) is seizing. What is the treatment?",', '["Intravenous bolus of 2 mL/kg of 10% Dextrose (D10W)", "Oral glucose gel", "Intramuscular Epinephrine", "Intravenous Calcium Gluconate"]', 0, 'Symptomatic hypoglycemia (seizures, lethargy) requires immediate IV glucose. D10W is the standard concentration for neonates to avoid vein sclerosis. (First Aid)'),
    (v_topic_id, '329: A neonate presents with delayed umbilical cord separation (>3 weeks), recurrent skin infections without pus formation, and severe gingivitis. What is the immune defect?",', '["Leukocyte Adhesion Deficiency (LAD)", "Severe Combined Immunodeficiency (SCID)", "Chronic Granulomatous Disease (CGD)", "X-linked Agammaglobulinemia"]', 0, 'LAD involves a defect in the CD18 integrin. Neutrophils cannot adhere to endothelium to exit the bloodstream. This leads to extremely high WBC counts in the blood, but no neutrophils at the site of infection (hence, no pus). (UWorld)'),
    (v_topic_id, '330: A newborn is diagnosed with Severe Combined Immunodeficiency (SCID) via newborn screen (low TRECs). What is the definitive cure?",', '["Hematopoietic stem cell transplant (Bone marrow transplant)", "Intravenous Immunoglobulin (IVIG) monthly", "Prophylactic antibiotics for life", "Thymus transplant"]', 0, 'SCID (absence of T cells, and secondary B cell failure) is universally fatal in infancy without a stem cell transplant to provide a functional immune system. (Case Files)'),
    (v_topic_id, '331: A neonate presents with an umbilical hernia, a large tongue, and hypotonia. A blood test shows an elevated TSH and low free T4. Diagnosis?",', '["Congenital Hypothyroidism", "Down Syndrome", "Beckwith-Wiedemann Syndrome", "Pompe Disease"]', 0, 'Classic signs of congenital hypothyroidism. Early detection and treatment with levothyroxine are critical to prevent profound intellectual disability. (Amboss)'),
    (v_topic_id, '332: A neonate is found to have ambiguous genitalia. A karyotype is 46,XX. Ultrasound reveals normal ovaries and a uterus. What is the most likely cause of virilization?",', '["Exposure to high levels of androgens in utero (e.g., Congenital Adrenal Hyperplasia)", "Absence of the SRY gene", "Testicular feminization syndrome", "Turner syndrome"]', 0, 'The presence of ovaries and a uterus confirms female internal structures. Virilization of the external genitalia is caused by androgen exposure, overwhelmingly due to 21-hydroxylase deficiency (CAH). (Nelson)'),
    (v_topic_id, '333: A 3-day-old infant develops a harsh, high-pitched systolic murmur. Echocardiogram shows a thickened, restrictive pulmonary valve with post-stenotic dilation of the pulmonary artery. Diagnosis?",', '["Pulmonary Valve Stenosis", "Tetralogy of Fallot", "Atrial Septal Defect", "Patent Ductus Arteriosus"]', 0, 'Isolated pulmonary stenosis is a common congenital defect. If severe, it can present in the neonatal period with cyanosis (if R->L shunting occurs across a PFO). (First Aid)'),
    (v_topic_id, '334: A newborn has a completely imperforate anus. What must be done BEFORE attempting definitive surgical repair?",', '["Evaluate for other VACTERL anomalies and perform a diverting colostomy if the defect is high/complex", "Immediate pull-through procedure", "Barium enema", "Manual dilation"]', 0, 'Imperforate anus is highly associated with VACTERL. A high defect usually requires a temporary colostomy to allow the infant to grow and pass stool while a complex reconstructive surgery is planned. (UWorld)'),
    (v_topic_id, '335: A neonate is born with their bladder completely exposed and everted on the lower abdominal wall. Diagnosis?",', '["Bladder Exstrophy", "Prune Belly Syndrome", "Omphalocele", "Patent Urachus"]', 0, 'Bladder exstrophy is a severe midline abdominal wall defect. The bladder mucosa is exposed to the outside. Requires complex staged surgical repair. (Case Files)'),
    (v_topic_id, '336: A neonate presents with a persistent, clear fluid draining from the umbilicus. The fluid has a high creatinine concentration. Diagnosis?",', '["Patent Urachus", "Omphalomesenteric duct cyst", "Meckel diverticulum", "Umbilical granuloma"]', 0, 'The urachus connects the fetal bladder to the umbilicus. If it fails to obliterate, urine (high creatinine) leaks from the umbilicus. (Amboss)'),
    (v_topic_id, '337: A neonate presents with a persistent, foul-smelling, bilious fluid draining from the umbilicus. Diagnosis?",', '["Patent Omphalomesenteric (Vitelline) Duct", "Patent Urachus", "Umbilical hernia", "Gastroschisis"]', 0, 'The vitelline duct connects the fetal midgut to the yolk sac. If it fails to obliterate completely, it forms a fistula, leaking intestinal contents. (Nelson)'),
    (v_topic_id, '338: A newborn presents with a small, red, friable nodule deep in the umbilicus after the cord has fallen off. It is treated successfully with silver nitrate. Diagnosis?",', '["Umbilical granuloma", "Patent urachus", "Omphalitis", "Hemangioma"]', 0, 'An umbilical granuloma is common tissue overgrowth after cord separation. Silver nitrate chemically cauterizes it. (First Aid)'),
    (v_topic_id, '339: A 5-day-old infant presents with erythema, induration, and purulent discharge surrounding the umbilical stump. The infant is febrile and lethargic. Diagnosis and management?",', '["Omphalitis; Requires immediate hospitalization and IV antibiotics", "Umbilical granuloma; Treat with silver nitrate", "Normal cord separation; Observe", "Candidiasis; Topical antifungal"]', 0, 'Omphalitis is a life-threatening infection of the umbilical stump that can rapidly spread along the umbilical vessels to cause portal vein thrombosis, sepsis, or necrotizing fasciitis. (UWorld)'),
    (v_topic_id, '340: Final Pearl: A premature infant develops severe feeding intolerance, abdominal distension, and bloody stools. X-ray shows pneumatosis intestinalis. What is the absolute most critical first step in management?",', '["Make the infant strictly NPO (stop all enteral feeds), start IV fluids, and order broad-spectrum IV antibiotics", "Perform an immediate exploratory laparotomy", "Administer a contrast enema to rule out intussusception", "Give oral vancomycin"]', 0, 'This is Necrotizing Enterocolitis. Bowel rest and systemic antibiotics are the cornerstone of initial medical management to prevent perforation. (MediHelp Mastery)');
